#!/usr/bin/env python
import contextlib as __stickytape_contextlib

@__stickytape_contextlib.contextmanager
def __stickytape_temporary_dir():
    import tempfile
    import shutil
    dir_path = tempfile.mkdtemp()
    try:
        yield dir_path
    finally:
        shutil.rmtree(dir_path)

with __stickytape_temporary_dir() as __stickytape_working_dir:
    def __stickytape_write_module(path, contents):
        import os, os.path

        def make_package(path):
            parts = path.split("/")
            partial_path = __stickytape_working_dir
            for part in parts:
                partial_path = os.path.join(partial_path, part)
                if not os.path.exists(partial_path):
                    os.mkdir(partial_path)
                    with open(os.path.join(partial_path, "__init__.py"), "wb") as f:
                        f.write(b"\n")

        make_package(os.path.dirname(path))

        full_path = os.path.join(__stickytape_working_dir, path)
        with open(full_path, "wb") as module_file:
            module_file.write(contents)

    import sys as __stickytape_sys
    __stickytape_sys.path.insert(0, __stickytape_working_dir)

    __stickytape_write_module('config.py', b'import json\r\n\r\nclass ConfigFile:    \r\n    def __init__(self, filename="settings.json"):\r\n        self.__data = {}\r\n        try: \r\n            with open(filename, "r") as file:\r\n                self.__data = json.load(file)\r\n        except:\r\n            print(f"Couldn\'t read config file {filename}. Falling back to default values...")\r\n\r\n    def get(self, key, default_value = None):\r\n        return self.__data.get(key, default_value)\r\n    ')
    __stickytape_write_module('director.py', b'from numpy import rint\r\n\r\nfrom robot import Robot, MAX_VEL\r\nfrom navigation.navigator import Navigator\r\nfrom tile_classifier import TileClassifier, TileType\r\nfrom image import ImageProcessor\r\nfrom lidar import LidarProcessor, Side\r\nfrom comm import Comm\r\nfrom comm import MessageType\r\n# from mapping.mapper import Mapper\r\nfrom mapping.mapper_new_resolution import Mapper\r\n# from mapping.map import TILE_SIZE\r\nfrom mapping.map_new_resolution import TILE_SIZE\r\nimport math\r\nimport cv2\r\nimport utils\r\nfrom visualization.visualizer import Visualizer\r\nfrom vector import Vector\r\nfrom collections import deque\r\nfrom datetime import datetime\r\nimport statistics\r\nimport inspect\r\n\r\nVICTIMS_SENDING_DIST = 0.052 # Wall distance when analyzing images\r\nCOGNITIVE_SENDING_DIST = 0.057\r\nCOGNITIVE_ANALYZING_DIST = 0.072\r\nLIMIT_STEPS = 50\r\nPOS_SAMPLES = 4\r\n\r\nBASE_TESTING_DIST = 0.17508681\r\n\r\nACCURACY = TILE_SIZE/4\r\nROBOT_RADIUS = 0.035\r\n\r\nDEBUGGING_3_CAMS = True\r\n\r\nclass GameState:\r\n    def __init__(self):\r\n        self.game_score = 0\r\n        self.time_remaining = 10000\r\n        self.real_time_remaining = 10000\r\n        self.battery = 100.0\r\n\r\nclass Director:\r\n    def __init__(self, config):\r\n        self.config = config\r\n        self.robot = Robot()\r\n        self.last_robot_pos = self.robot.get_position()\r\n        self.navigator = Navigator()\r\n        self.tile_classifier = TileClassifier()\r\n        self.image_processor = ImageProcessor()\r\n        self.lidar_processor = LidarProcessor()\r\n        self.comm = Comm(self.robot)\r\n        self.game_state = GameState()\r\n        self.mapper=Mapper()\r\n        self.path = None\r\n        self.target_idx = -1\r\n        self.img_counter = 0\r\n        self.current_robot_area = None\r\n        self.last_robot_area = None\r\n        self.visualizer = Visualizer(config)\r\n\r\n        self.step_counter = 0\r\n        self.robot.on_step(self.on_step)\r\n\r\n        self.detected_signs = {}\r\n        self.pending_signs = []\r\n\r\n        self.robot_state = None\r\n\r\n        self.swamps_visits = {}\r\n        \r\n        self.grid_pos_path = []\r\n\r\n        self.detected_obstacles = []\r\n\r\n    def on_step(self):\r\n        """Director\'s step, in which key actions are performed without making the robot class \'knowing\' the director class,\r\n        in order to mantain our code\'s architecture (callback algorithm)"""\r\n        self.step_counter += 1\r\n        self.process_messages()\r\n\r\n        if self.step_counter % 10 == 0:\r\n            self.comm.send_gamescore_and_time_remaining_request()\r\n\r\n        self.navigator.mark_position_as_visited(self.robot.get_position())\r\n\r\n        self.visualizer.step()\r\n        self.visualizer.send_robot(self.robot)\r\n\r\n        self.update_pending_signs()\r\n\r\n    def __on_step(self): #DEBUG ON_STEP\r\n        return     \r\n\r\n    def update_pending_signs(self):\r\n        """Updates our pending_signs list while the robot is navigating, basing on the camera\'s output."""\r\n        nearby_signs = self.get_nearby_signs()\r\n        for est_sign_pos in nearby_signs:\r\n            if self.get_pending_sign_index(est_sign_pos) == -1:\r\n                self.pending_signs.append(est_sign_pos)\r\n                # print(f"Added pending sign at pos: {est_sign_pos[0]} with analyzing target pos: {est_sign_pos[1]}")\r\n\r\n    def get_pending_sign_index(self, sign_pos):\r\n        """With a recieved est. sign pos, we verify if the sign is already in the list or really close to an already detected one, to return its index, \r\n        or if its not, and the robot detected a new sign."""\r\n        sign_index = 0\r\n        for pending_sign_pos in self.pending_signs:\r\n            if pending_sign_pos[0].distance_to(sign_pos[0]) < 0.0335:\r\n                return sign_index\r\n            sign_index += 1\r\n        return -1\r\n    \r\n    def get_nearby_signs(self):\r\n        """All sign detection/update logic."""\r\n        return self.get_nearby_signs_with_3_cams()\r\n    \r\n    def get_nearby_signs_with_3_cams(self):\r\n        """All sign detection/update logic."""\r\n        # print("Checking nearby signs with 3 cams...")\r\n        lidar_image = self.robot.get_lidar_image()\r\n        robot_direction = self.robot.get_forward_vector()\r\n        pending_signs_pos = []\r\n        is_cognitive = False\r\n        is_zoomed_in = False\r\n        \r\n        for side in Side:\r\n            if side == Side.BACK:\r\n                continue\r\n            # 1) Verify if the robot is near a wall, and if it is aligned to it, to check if there is a sign in the camera\'s image.\r\n            if self.lidar_processor.is_wall_at_side(lidar_image, side):\r\n                if self.lidar_processor.is_aligned_to_wall(lidar_image, side, robot_direction):\r\n                    point = self.get_estimated_sign_pos(lidar_image[side.value], side.get_angle())\r\n                    if not self.is_sign_detected(point):\r\n                        image = self.robot.get_camera_from_side(side)\r\n                        if self.image_processor.is_victim(image):\r\n                            is_cognitive = False\r\n                        elif self.image_processor.is_cognitive(image):\r\n                            is_cognitive = True\r\n                        elif self.image_processor.is_image_zoomed_in(image):\r\n                            if not min(lidar_image[side.value - 6:side.value + 6]) <= 0.055: \r\n                                continue\r\n                            if self.image_processor.is_zoomed_image_a_victim(image): # Basing on the colours of the image, we can determine if\r\n                                # the zoomed image is a victim or a cognitive sign.\r\n                                is_cognitive = False\r\n                            else:\r\n                                is_cognitive = True\r\n                            # print(f"Is zoomed image a victim? {not is_cognitive}")\r\n                            is_zoomed_in = True\r\n                        else:\r\n                            continue\r\n                        # self.record(special_case=False, camera=side)\r\n\r\n                        centre = self.image_processor.get_contour_centre(image, is_cognitive, is_zoomed_in)\r\n                        if centre is None:\r\n                            # print(f"No contour\'s center found at side {side.name}!")\r\n                            continue \r\n                        ray_offset = self.calculate_lidar_offset(centre - 20, lidar_image, side)\r\n                        token_pos, target_pos = self.get_estimated_analyzing_pos(side, ray_offset, is_cognitive) # Best transitable point for the robot to analyze the sign.\r\n                        if target_pos is None: continue\r\n                        self.record(special_case=False, camera=side)\r\n                        pending_signs_pos.append((token_pos, target_pos, is_cognitive))\r\n\r\n        return pending_signs_pos\r\n\r\n    def update_visualizer(self):\r\n        self.visualizer.update(self)\r\n\r\n    def __start(self): # DEBUG\r\n        while self.robot.step():\r\n            print("-"*30)\r\n\r\n    def start(self):\r\n        """Main loop of the director class, which controls the robot\'s actions and navigation."""\r\n        self.current_robot_area = 1\r\n        self.previous_robot_area = 1\r\n        self.mapper.add_tiles({(0,0): TileType.STARTING})\r\n        self.mapper.set_area(self.mapper.get_tile_at_pos((0,0)), self.current_robot_area)\r\n        print(f"Initial tile at pos (0,0): {self.mapper.get_tile_at_pos((0,0))}")\r\n        self.mapper.add_visited_tile(self.mapper.get_tile_at_pos((0,0)))\r\n\r\n        while True:\r\n            robot_pos = self.robot.get_position()\r\n            abs_pos = self.robot.get_absolute_position()\r\n\r\n            self.process_messages()\r\n            self.update_maps()\r\n            self.update_visits(robot_pos)\r\n            self.update_path()\r\n            self.update_cameras()\r\n            self.pending_signs = []\r\n            self.update_visualizer()\r\n            # self.record(False)\r\n\r\n            # If the path is empty, we break out of the loop\r\n            if self.path is not None and len(self.path) == 0:\r\n                self.navigator.map.increase_visit_count((0, 0), 0)\r\n                break\r\n\r\n            # If theres no time left, we send an early exit\r\n            if self.game_state.time_remaining <= 10 or self.game_state.real_time_remaining <= 10:\r\n                break\r\n\r\n            self.move_to_target()\r\n\r\n            # Save the robot position at the beginning of the loop in order to\r\n            # mark this point as not traversable in case of LOP\r\n            self.last_robot_pos = robot_pos\r\n            self.robot.last_absolute_position = abs_pos\r\n            if self.robot.is_lop:\r\n                self.robot.is_lop = False\r\n\r\n        nav_map_img = self.navigator.map.get_image()\r\n        if nav_map_img is not None:\r\n            cv2.imwrite("nav_map.png", nav_map_img)\r\n            \r\n        self.visualizer.stop()\r\n        final_map = self.mapper.mapping_pixels(self.robot.start_pos)\r\n        self.comm.send_map(final_map)\r\n        self.robot.stop()\r\n        self.robot.delay(5000)\r\n        self.comm.send_exit()\r\n\r\n\r\n    def move_to_target(self):\r\n        """Moves the robot towards the current target in the path, handling obstacles and marking visited positions."""\r\n        if self.path is None: return\r\n        target = self.path[self.target_idx]\r\n        if not self.robot.move_to_point(target, 0.015, blocking_steps=1): # If the robot did not arrive to dest.\r\n            # print((f"ESTOY ATASCADO:  {self.robot.is_stuck()}"))\r\n            if self.robot.is_stuck():\r\n                print(f"{self.step_counter} THE ROBOT IS STUCK!")\r\n                self.navigator.mark_position_as_obstructed(target)\r\n                self.robot.stop()\r\n                self.target_idx += 1\r\n                if self.target_idx >= len(self.path):\r\n                    self.path = None\r\n                    self.target_idx = -1\r\n            return\r\n\r\n        # If execution reaches this line, we arrived to the target\r\n        self.robot.stop()\r\n        self.navigator.mark_position_as_visited(target)\r\n\r\n        self.target_idx += 1\r\n        if self.target_idx >= len(self.path):\r\n            self.path = None\r\n            self.target_idx = -1\r\n        # print(f"Minitiles dict after moving to target: {self.navigator.map.minitiles}")\r\n\r\n    def process_messages(self):\r\n        """Processes incoming messages from the communication module, updating the game state and handling LOP events."""\r\n        self.robot.is_lop = False\r\n        messages = self.comm.get_messages()\r\n        for message in messages:  #[(\'G\', 12.2, 14, 28), (\'L\')]\r\n            if message[0] == MessageType.GAME_INFO:\r\n                self.game_state.game_score = message[1]\r\n                self.game_state.time_remaining = message[2]\r\n                self.game_state.real_time_remaining = message[3]\r\n                self.game_state.battery=message[4] \r\n                print(f"Battery: {self.game_state.battery}")\r\n            elif message[0] == MessageType.LOP:\r\n                print(f"LOP detected in process_messages! Step: {self.step_counter}")\r\n                self.robot.is_lop = True\r\n                self.navigator.mark_lop(self.last_robot_pos)\r\n                self.visualizer.send_debug({"lop": self.last_robot_pos})\r\n                self.path = None\r\n                self.target_idx = -1\r\n                self.robot.set_corrected_position_by_lop(self.robot.get_absolute_position(), 0.06)\r\n\r\n    def update_maps(self):\r\n        """Updates the maps with the robot\'s current position, lidar points, and surrounding tiles."""\r\n        robot_pos = self.robot.get_position()\r\n        lidar_points = self.robot.get_lidar_points()\r\n        surrounding_tiles = self.tile_classifier.get_surrounding_tiles(self.robot)\r\n        self.mapper.update(robot_pos, lidar_points, surrounding_tiles)\r\n        self.navigator.update(robot_pos, lidar_points, surrounding_tiles)\r\n        # obstacle_average = None\r\n        obstacle_points = self.possible_obstacles(self.robot.lidar)\r\n        if obstacle_points:\r\n            obstacle_pos = obstacle_points[0]\r\n            obstacle_relative = obstacle_pos - self.robot.start_pos\r\n            obstacle_tile = self.tile_classifier.position_to_grid(obstacle_relative)\r\n            self.mapper.add_obstacles(obstacle_tile)\r\n        \r\n        current_grid_pos = self.tile_classifier.position_to_grid(robot_pos)\r\n        is_current_tile_visited = self.mapper.is_tile_in_visited_tiles(current_grid_pos)\r\n        current_tile = self.mapper.get_tile_at_pos(current_grid_pos)\r\n        if len(self.grid_pos_path) == 0 or self.grid_pos_path[-1] != current_grid_pos:\r\n            self.grid_pos_path.append(current_grid_pos)\r\n\r\n        # print(f"Visited tiles path: {self.grid_pos_path}")\r\n        if not is_current_tile_visited and current_tile is not None:\r\n            if not self.mapper.is_color_passage(current_tile):\r\n                if len(self.mapper.visited_tiles) > 1:\r\n                    idx = -2\r\n                    last_grid_pos_visited = self.grid_pos_path[idx] # NOTE(Martu): The last index of the list is the current tile, we want the one before it.\r\n                    last_added_tile = self.mapper.get_visited_tile_at_pos(last_grid_pos_visited)\r\n                    if last_added_tile is None:\r\n                        for visited_grid_pos in self.grid_pos_path[:-1][::-1]: # We iterate the grid pos path backwards, starting from the one before the current tile, to find the last visited tile.\r\n                            """Here we are trying to fix the problem of the tile_classifier do not finding a surrounded tile, which causes the mapper to do not\r\n                            add the tile to the visited tiles, and then, when we find a new tile, we do not have any reference of the area of the last tile to \r\n                            calculate the new tile\'s area. This bug raises an error, so now if we do not find any visited tile, we iterate the grid pos path backwards\r\n                            to find the last visited tile, which should be the last tile added to the visited tiles."""\r\n                            idx -= 1\r\n                            last_added_tile = self.mapper.get_visited_tile_at_pos(visited_grid_pos)\r\n                            if last_added_tile is not None:\r\n                                break\r\n                            else:\r\n                                continue\r\n                    if self.mapper.is_color_passage(last_added_tile):\r\n                        last_area_before_passage = self.mapper.get_visited_tile_at_pos(self.grid_pos_path[idx - 1]).area\r\n                        area = self.mapper.get_new_area(last_area_before_passage, last_added_tile)\r\n                        current_tile.area = area\r\n                        self.current_robot_area = area\r\n                    else:\r\n                        current_tile.area = last_added_tile.area\r\n                        self.current_robot_area = last_added_tile.area\r\n                else:\r\n                    current_tile.area = 1\r\n                    self.current_robot_area = 1\r\n            else:\r\n                current_tile.area = None\r\n                self.current_robot_area = None\r\n\r\n            self.mapper.add_visited_tile(current_tile)\r\n\r\n        if current_tile is not None:\r\n            for tile in surrounding_tiles:\r\n                tile = self.mapper.get_tile_at_pos(tile)\r\n                if current_tile.area is not None and tile.tile_type == TileType.BLACK_HOLE:\r\n                    """his logic is to set area to the black hole tiles, so that they are always mapped with \'*\' in the matriz if they are\r\n                    inside the area 4."""\r\n                    tile.area = current_tile.area\r\n\r\n    def update_path(self):\r\n        """Updates the robot\'s path to the next target, recalculating it if the current target is obstructed or unreachable."""\r\n        robot_pos = self.robot.get_position()\r\n        target = self.path[self.target_idx] if self.path is not None else None\r\n        if target is None or not self.navigator.is_traversable(target):\r\n            if target is not None:\r\n                for i in range(self.target_idx, len(self.path)):\r\n                    self.navigator.mark_position_as_obstructed(self.path[i])\r\n            path = self.navigator.find_path(robot_pos)\r\n            self.path = path\r\n            self.target_idx = 0\r\n\r\n    def update_visits(self, robot_pos):\r\n        """Updates the visit count for the swamps based on the robot\'s movement between the actual position and the last position."""\r\n        last_minitile_vector = self.navigator.map.world_to_minitile(self.last_robot_pos)\r\n        last_minitile = (last_minitile_vector.x, last_minitile_vector.y)\r\n        actual_minitile_vector = self.navigator.map.world_to_minitile(robot_pos)\r\n        actual_minitile = (actual_minitile_vector.x, actual_minitile_vector.y)\r\n        if last_minitile != actual_minitile:\r\n            if last_minitile in self.swamps_visits:\r\n                # print(F"ya estuve aqui")\r\n                increment = self.swamps_visits[last_minitile] + 1.5\r\n                # self.swamps_visits[last_minitile] = increment\r\n            else:\r\n                increment = 1.5 # recomendado por Claude despu\xc3\xa9s de analizar el costo de los swamps, \r\n            # para que el robot empiece a evitarlos despu\xc3\xa9s de 2 visitas (siendo el costo de la visita 8 + 1.5 * visits, y el costo del desv\xc3\xado 24)\r\n            self.swamps_visits[last_minitile] = increment\r\n            self.navigator.map.increase_visit_count(last_minitile, increment)\r\n            # print(f"LAST MINITILE {last_minitile} ------- INCREMENT {increment}")\r\n            \r\n\r\n    def calculate_lidar_offset(self, centre_offset, lidar_image, side):\r\n        """Calculates the offset in rays from the centre of the camera\'s image to the centre of the sign\'s contour."""\r\n        delta_angle = math.pi * 2 / 512\r\n        total_angle = 27 * delta_angle # NOTE (Martu): 27 is the amount of rays inside the camera\'s half image (20 pixels).\r\n\r\n        dist_offset = math.tan(total_angle) * lidar_image[side.value]\r\n        dist_offset = (centre_offset * dist_offset) / 20\r\n        offset_angle = math.atan2(dist_offset, lidar_image[side.value])\r\n        rays = math.floor(offset_angle / delta_angle)\r\n        return rays\r\n\r\n    def update_cameras(self):\r\n        """Updates the robot\'s cameras to look at the nearest detected sign, if any, and places the robot to analyze it."""\r\n        while not len(self.pending_signs) == 0:\r\n            pos = self.robot.get_position()\r\n            self.pending_signs.sort(key=lambda x: x[1].distance_to(pos))\r\n            token_point, target_pos, is_cognitive = self.pending_signs[0]\r\n\r\n            if target_pos.distance_to(pos) > TILE_SIZE: \r\n                self.pending_signs = []\r\n                return None\r\n\r\n            # 1) Move to target pos (given by get_estimated_analyzing_pos)\r\n            self.robot.look_at(target_pos - self.robot.get_position())\r\n            self.robot.advance(self.robot.get_position().distance_to(target_pos), 0.002)\r\n            # self.record()\r\n\r\n            # 2) Look at token point (sign\'s centre)\r\n            self.robot.look_at(token_point - self.robot.get_position(), 0.001)\r\n\r\n            self.try_center_sign(analyzing_after_placing = True)\r\n            self.try_approach_sign(is_cognitive)\r\n\r\n            self.robot.stop()\r\n\r\n            if self.robot.is_lop: \r\n                """If a lop happens in this point, we stop the analyze, so on the next step, the robot will be able to recover from it.\r\n                Here, the robot will crash"""\r\n                self.pending_signs = []\r\n                return None\r\n            \r\n            self.record(special_case=False, camera=Side.FRONT)\r\n            if is_cognitive:\r\n                self.analyze_cognitive_sign()\r\n            else:\r\n                self.analyze_victim_sign()\r\n            print("-"*70)\r\n            self.pending_signs.pop(0)\r\n\r\n    def get_estimated_sign_pos(self, lidar_dist, target_rot):\r\n        """Estimates the position of a sign based on lidar distance and target rotation."""\r\n        rot = self.robot.get_forward_vector().rotated(target_rot)\r\n        sign_pos = self.robot.get_position() + rot * lidar_dist\r\n        return sign_pos\r\n\r\n    def is_sign_detected(self, sign_pos):\r\n        """Checks if a sign is already detected if its position is near to an already registered sign."""\r\n        for key in self.detected_signs.keys():\r\n            dict_sign_pos = key[0]\r\n            if dict_sign_pos.distance_to(sign_pos) < 0.0335:\r\n                return True\r\n        return False\r\n    \r\n    def possible_obstacles(self, lidar, distance = 0.08):\r\n        """Checks for possible obstacles around the robot using camera data."""\r\n        image_lidar = lidar.getRangeImage()\r\n        layer4 = image_lidar[1536:2048]\r\n\r\n        for side in [Side.FRONT, Side.LEFT, Side.RIGHT]:\r\n            result = self._check_camera_obstacle(layer4, side, distance)\r\n            # print(f"RESULTADO {result}")\r\n            if result:\r\n                return result\r\n        return False\r\n    \r\n    def _check_camera_obstacle(self, layer4, side, distance):\r\n        """Checks for obstacles in the camera\'s image, uses lidar data to estimate its position."""\r\n        ray_index = side.value \r\n        ray_value = layer4[ray_index]\r\n        # print(f"DISTANCIAAAA {ray_value}")\r\n        if ray_value > distance:\r\n            return False\r\n        camera_side = self.robot.get_camera_from_side(side)\r\n        # print(f"SIDE:  {camera_side}")\r\n        # print(f"SIDE {side}")\r\n        if self.image_processor.is_cognitive(camera_side) or self.image_processor.is_victim(camera_side):\r\n            # print("IS COGNITIVE??", self.image_processor.is_cognitive(camera_side))\r\n            # print("IS VICTIM??", self.image_processor.is_victim(camera_side))\r\n            # print("Un sign...")\r\n            return False\r\n        \r\n        obstacles_px = self.image_processor.count_continuous_obs_pixels(camera_side)\r\n        \r\n        if obstacles_px < 18:\r\n            # print(f"PIXELES OBTACULOS {obstacles_px}")\r\n            return False\r\n        # if obstacles_px > 25:\r\n        #     print(f"PIXELES OBTACULOS MAYORES A 25 {obstacles_px}")\r\n            \r\n        ray_angle = ray_index * (360.0 / 512.0)\r\n        # angle_offset = -ray_angle # FRONT = -180, LEFT -90, RIGHT = -270\r\n        angle_rad = math.radians(ray_angle - 180.0)\r\n\r\n        yaw = self.robot.get_rotation()\r\n        robot_pos = self.robot.get_position() + self.robot.start_pos\r\n\r\n        \r\n        x_obstacle = ray_value * math.sin(angle_rad)\r\n        z_obstacle = ray_value * math.cos(angle_rad)\r\n\r\n        x_final = robot_pos.x + (x_obstacle * math.cos(yaw) - z_obstacle * math.sin(yaw))\r\n        z_final = robot_pos.y - (x_obstacle * math.sin(yaw) + z_obstacle * math.cos(yaw))\r\n        \r\n        final_point = Vector(x_final, z_final)\r\n        final_point_rel = final_point - self.robot.start_pos\r\n\r\n        for key in self.detected_signs.keys():\r\n            dict_sign_pos = key[0]\r\n            dict_robot_pos = key[1]\r\n            robot_position = self.robot.get_position()\r\n            if dict_sign_pos.distance_to(final_point_rel) < 0.065 and dict_robot_pos.distance_to(robot_position) < 0.065:\r\n                # print(f"CLOSE TO A SIGN, PROBABLY NOT AN OBSTACLE!!.")\r\n                return False\r\n            \r\n        for obstacles_position in self.detected_obstacles:\r\n            if obstacles_position.distance_to(final_point) < 0.07:\r\n                # print("Close to another obsacle...")\r\n                return False\r\n            \r\n        # print("Final point:", final_point)\r\n        \r\n        self.detected_obstacles.append(final_point)\r\n        # obstacle_points.append(final_point) \r\n        # print(f"FINAL POINT {[final_point]}")\r\n        return [final_point]\r\n\r\n\r\n    def try_center_sign(self, min_tol = 18, max_tol = 21, analyzing_after_placing = False):\r\n        """Tries to center the sign in the image by rotating until the contour\'s center is within the specified tolerance range."""\r\n        # print(f"Intentando centrar en step {self.step_counter}")\r\n        steps = 0\r\n        while not self.robot.is_stuck() and not self.robot.is_lop:\r\n            # print(f"Step {steps}")\r\n            img = self.robot.get_camera_from_side(Side.FRONT)\r\n            centre = self.image_processor.get_contour_centre(img, analyzing_after_placing)\r\n            if steps >= LIMIT_STEPS:\r\n                # print(f"Could not center sign after {steps} steps, breaking.")\r\n                break\r\n\r\n            if centre is None: break\r\n            centre = round(centre, 4)\r\n            # print(f"Contour centre: {centre}")\r\n            vel = 6.28/12\r\n            if centre > max_tol:\r\n                self.robot.set_velocity(vel, -vel)\r\n            elif centre < min_tol:\r\n                self.robot.set_velocity(-vel, vel)\r\n            else:\r\n                break\r\n\r\n            if not self.robot.step():\r\n                # print(f"Robot is stuck while trying to center sign, breaking.")\r\n                break\r\n\r\n            steps += 1\r\n\r\n        self.robot.stop()\r\n\r\n    def move_and_centre(self, distance, margin=0.001, *, blocking_steps=-1):\r\n        """Moves the robot a specified distance while trying to center the sign in the image."""\r\n        initial_pos = self.robot.get_position()\r\n\r\n        is_done = False\r\n        steps = 0\r\n        while not self.robot.is_stuck() and not self.robot.is_lop:\r\n            self.try_center_sign()\r\n\r\n            traveled_dist = self.robot.get_position().distance_to(initial_pos)\r\n            diff = abs(distance) - traveled_dist\r\n            # print(f"Diff of move and centre: {diff}")\r\n            if diff <= margin:\r\n                is_done = True\r\n                self.robot.stop()\r\n                break\r\n\r\n            vel = min(max(diff/0.01, 0.1), 1) * 6.28\r\n            if distance < 0: vel *= -1\r\n\r\n            if vel > 0 and min(self.robot.get_lidar_image()[Side.FRONT.value-45:Side.FRONT.value+45]) > 0.044:\r\n                self.robot.set_velocity(vel, vel)\r\n            elif vel < 0 and min(self.robot.get_lidar_image()[Side.BACK.value: Side.BACK.value+45] + self.robot.get_lidar_image()[Side.BACK.value+467:Side.BACK.value+512]) > 0.044:\r\n                self.robot.set_velocity(vel, vel)\r\n            else:\r\n                self.robot.stop()\r\n                break\r\n\r\n            if blocking_steps == steps:\r\n                break\r\n            if not self.robot.step():\r\n                break\r\n\r\n            steps += 1\r\n\r\n        return is_done\r\n\r\n    def get_estimated_analyzing_pos(self, side, ray_offset, is_cognitive=False):\r\n        """Calculates the most accurate analyzing position for the robot based on the estimated sign position."""\r\n        central_ray = side.value\r\n        delta_ang = -math.pi*2/512\r\n        target_rot = side.get_angle() + ray_offset * delta_ang\r\n\r\n        dist_a = self.robot.get_lidar_image()[central_ray + ray_offset] # Distance to the sign\'s center, based on the lidar\'s image.\r\n        dist_b = self.robot.get_lidar_image()[central_ray + ray_offset + 2]\r\n        if abs(dist_a) == math.inf or abs(dist_b) == math.inf:\r\n            return None, None\r\n\r\n        direction = self.robot.get_forward_vector().rotated(target_rot)\r\n        a = self.robot.get_position() + (direction * dist_a)\r\n        b = self.robot.get_position() + (direction * dist_b).rotated(delta_ang * 2) # Multiplied by the amount of rays between dist_a and dist_b.\r\n\r\n        # print(f"b: {b}, a: {a}")\r\n        if not is_cognitive:\r\n            c = (b - a).normalized() * VICTIMS_SENDING_DIST\r\n        else:\r\n            c = (b - a).normalized() * COGNITIVE_SENDING_DIST\r\n        c = c.rotated(-math.pi/2)\r\n        c += a # Middle point between a and b, but rotated 90 degrees to the left, to get the best analyzing position for the robot.\r\n\r\n        target = self.navigator.find_closest_traversable_point(c, self.robot.get_position(), True)\r\n        if target is not None and self.get_pending_sign_index((a, target)) == -1:\r\n            self.visualizer.send_debug({"a": a,\r\n                            "b": b,\r\n                            "t": target})\r\n\r\n        if not abs(target.distance_to(a)) > 0.09:\r\n            return a, target\r\n        return None, None\r\n\r\n    def try_approach_sign(self, is_cognitive=False):\r\n        """Makes the robot approach the sign while trying to center it in the camera\'s image, to get a better analyzing result."""\r\n        front_tol = None\r\n        if is_cognitive:\r\n            front_tol = (min(self.robot.get_lidar_image()[240: 282]) - COGNITIVE_ANALYZING_DIST)\r\n        else:\r\n            front_tol = (min(self.robot.get_lidar_image()[240: 282]) - VICTIMS_SENDING_DIST)\r\n        if front_tol is not None:\r\n            self.move_and_centre(front_tol, 0.002, blocking_steps = LIMIT_STEPS)\r\n\r\n    def analyze_victim_sign(self):\r\n        """Analyzes the victim sign by capturing an image and processing it."""\r\n        token = None\r\n        # print(f"Analyzing victim dist: {min(self.robot.get_lidar_image()[240: 272])}")\r\n        if min(self.robot.get_lidar_image()[240: 272]) < 0.04:\r\n            token = self.image_processor.analyze_zoomed_image(self.robot.get_camera_from_side(Side.FRONT), self.robot.get_position(), self.robot.get_forward_vector())\r\n            # print(f"ES VICTIMA: {token}")\r\n        else:\r\n            # print(f"Analyzing victim sign!")\r\n            token = self.image_processor.analyze_image(self.robot.get_camera_from_side(Side.FRONT), self.robot.get_position(), self.robot.get_forward_vector())\r\n        if token is not None:\r\n            print(f"Victim token: {token}")\r\n            token_pos = self.sending_and_mapping_sign(token)\r\n            # print("-"*60)\r\n            return token_pos\r\n        \r\n    def analyze_cognitive_sign(self):\r\n        """Analyzes the cognitive sign by capturing an image and processing it."""\r\n        token = None\r\n        # print(f"Analyzing cognitive sign!")\r\n        self.try_center_sign(min_tol = 19, max_tol = 20)\r\n        token = self.image_processor.analyze_image(self.robot.get_camera_from_side(Side.FRONT), self.robot.get_position(), self.robot.get_forward_vector())\r\n        if min(self.robot.get_lidar_image()[240: 272]) >= 0.06:\r\n            self.robot.advance(min(self.robot.get_lidar_image()[240: 272]) - COGNITIVE_SENDING_DIST, 0.002)\r\n        if token is not None:\r\n            print(f"Cognitive token: {token}")\r\n            token_pos = self.sending_and_mapping_sign(token)\r\n            # print("-"*60)\r\n            return token_pos\r\n\r\n    def sending_and_mapping_sign(self, token):\r\n        self.send_voc_message(token)\r\n\r\n    def send_voc_message(self, token, pos = None):\r\n        """Sends the token and its position to the supervisor, and adds it to the mapper if it\'s not a fake sign."""\r\n        self.robot.stop()\r\n        self.robot.delay(1500)\r\n        robot_direction = self.robot.get_forward_vector()\r\n        absolute_pos = self.robot.get_position() + self.robot.start_pos\r\n        relative_pos = self.robot.get_position()\r\n        dist = self.robot.get_lidar_image()[256]\r\n        absolute_token_pos = absolute_pos + robot_direction * dist\r\n        relative_token_pos = relative_pos + robot_direction * dist\r\n        if token != \'Z\' and token != \'X\': # If the token is not a fake sign (victim/cognitive) and a obstacle.\r\n            self.comm.send_token(int(absolute_token_pos.x * 100), int(absolute_token_pos.y * 100), token)\r\n            self.robot.delay(100)\r\n            if not self.current_robot_area == 4:\r\n                self.mapper.add_sign(token, absolute_token_pos, self.tile_classifier.position_to_grid(relative_token_pos))\r\n        # Adding the sign (wether real or fake) to the detected_signs dictionary, so that we do not analyze it infinitely.\r\n        self.detected_signs[(relative_token_pos, relative_pos)] = token\r\n\r\n    def record(self, special_case = False, camera = None, type_of_image = None): # JUST FOR TESTING!\r\n        """Records the images from the robot\'s cameras for testing purposes, saving them with a step counter in the erebus\r\n        game/controllers/robot0controller subfolder."""\r\n        if not self.config.get("record_enabled", False): return\r\n        if camera is not None:\r\n            if camera == Side.FRONT:\r\n                if type_of_image is None:\r\n                    cv2.imwrite(f"CF{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.FRONT))\r\n                else:\r\n                    cv2.imwrite(f"CF{str(self.step_counter).rjust(4, \'0\')}_{type_of_image}.png", self.robot.get_camera_from_side(Side.FRONT))\r\n            elif camera == Side.LEFT:\r\n                if type_of_image is None:\r\n                    cv2.imwrite(f"CI{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.LEFT))\r\n                else:\r\n                    cv2.imwrite(f"CI{str(self.step_counter).rjust(4, \'0\')}_{type_of_image}.png", self.robot.get_camera_from_side(Side.LEFT))\r\n            elif camera == Side.RIGHT:\r\n                if type_of_image is None:\r\n                    cv2.imwrite(f"CD{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.RIGHT))\r\n                else:\r\n                    cv2.imwrite(f"CD{str(self.step_counter).rjust(4, \'0\')}_{type_of_image}.png", self.robot.get_camera_from_side(Side.RIGHT))\r\n        else:\r\n            cv2.imwrite(f"CI{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.LEFT))\r\n            cv2.imwrite(f"CF{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.FRONT))\r\n            cv2.imwrite(f"CD{str(self.step_counter).rjust(4, \'0\')}.png", self.robot.get_camera_from_side(Side.RIGHT))')
    __stickytape_write_module('robot.py', b'from controller import Robot as WebotsRobot # type: ignore\r\nimport math\r\nimport utils\r\nimport numpy as np\r\nfrom vector import Vector\r\nfrom side import Side\r\nfrom filter import FrontLidarPositioner, EncoderPositioner\r\nimport traceback\r\nimport inspect\r\n\r\nMAX_VEL = 6.28\r\nTIME_STEP = 16\r\nLIMIT_STEPS = 100\r\nWHEEL_RADIUS = 0.026\r\nDIST_BETWEEN_WHEELS = 0.104\r\nMIN_POINTS_ICP = 4\r\nMAX_LIDAR_DIST = 1\r\nLIMIT_AVERAGE = 25\r\n\r\nDEBUGGING = False\r\nDEBUGGING_3_CAMS = True\r\nDEBUGGPSOK = False   # True: activa y usa gps_ok para comparar posici\xc3\xb3n; False: no lo habilita\r\n\r\nclass Robot:\r\n    def __init__(self):\r\n        self.robot = WebotsRobot()\r\n\r\n        self.wheel_left = self.robot.getDevice("wheel2 motor")\r\n        self.wheel_right = self.robot.getDevice("wheel1 motor")\r\n        self.wheel_left.setPosition(float(\'inf\'))\r\n        self.wheel_right.setPosition(float(\'inf\'))\r\n        self.stop()\r\n\r\n        self.enc_left = self.wheel_left.getPositionSensor()\r\n        self.enc_right = self.wheel_right.getPositionSensor()\r\n        self.enc_left.enable(TIME_STEP)\r\n        self.enc_right.enable(TIME_STEP)\r\n        \r\n        self.gps = self.robot.getDevice("gps")\r\n        self.gps.enable(TIME_STEP)\r\n\r\n        self.gps_ok = None\r\n        if DEBUGGPSOK:\r\n            self.gps_ok = self.robot.getDevice("gps_ok")\r\n            self.gps_ok.enable(TIME_STEP)\r\n\r\n        self.imu = self.robot.getDevice("inertial_unit")\r\n        self.imu.enable(TIME_STEP)\r\n\r\n        self.lidar = self.robot.getDevice("lidar")\r\n        self.lidar.enable(TIME_STEP)\r\n\r\n        self.front_camera = self.robot.getDevice("camaraFrontal")\r\n        self.front_camera.enable(TIME_STEP)\r\n\r\n        self.left_camera = self.robot.getDevice("camaraIzquierda")\r\n        self.left_camera.enable(TIME_STEP)\r\n\r\n        self.right_camera = self.robot.getDevice("camaraDerecha")\r\n        self.right_camera.enable(TIME_STEP)\r\n\r\n        self.distance_sensor = self.robot.getDevice("distance sensor1")\r\n        self.distance_sensor.enable(TIME_STEP)\r\n\r\n        self.receiver = self.robot.getDevice("receiver")\r\n        self.receiver.enable(TIME_STEP)\r\n        self.emitter = self.robot.getDevice("emitter")\r\n\r\n        self.is_moving = False\r\n        self.is_lop = False\r\n        self.previous_position = Vector.ZERO\r\n        self.previous_direction = Vector.ZERO\r\n        self.start_pos = None\r\n        self.stuck_counter = 0\r\n        self.step_callbacks = []\r\n\r\n        self.start_pos = None\r\n        self._last_time = None\r\n        self.first_dists = {}\r\n        self._lidar_image_cache = None\r\n\r\n        self.is_the_same_position = True\r\n        self.same_position_counter = 0\r\n        self.is_saving_gps_samples = False\r\n        self.max_diff_x = 0\r\n        self.max_diff_y = 0\r\n        \r\n        # utils.log_debug("Robot initialized")\r\n        self.raw_step()\r\n\r\n        self.gps_pos = np.array([Vector.ZERO for _ in range(LIMIT_AVERAGE)], dtype=object)\r\n\r\n        self.first_update = True\r\n        self.step_counter = 0\r\n        self.is_rotating = True\r\n        self.pos = Vector(0,0)\r\n\r\n        # self.odometry = FrontLidarPositioner(init_pos = Vector(0, 0))\r\n        self.odometry = EncoderPositioner(init_pos = Vector(0, 0))\r\n\r\n        self.step()\r\n        # utils.log_debug("First step completed")\r\n        raw_start_pos = self.get_absolute_position()\r\n        self.start_pos = utils.get_corrected_position(raw_start_pos, 0.06)\r\n        # print(f"Robot start position set to: {self.start_pos}") \r\n\r\n        self.last_absolute_position = self.start_pos\r\n\r\n    def set_corrected_position_by_lop(self, pos, margin):\r\n        """Sets the robot\'s perfect position if a LoP is executed."""\r\n        # NOTE (Martu): When making a LoP, the robot changes its position to the exact center of a tile, so we correct the GPS given position\r\n        # to make it a multiple of 0.06 (the half tile size) and set it as the robot\'s position.\r\n        pos = utils.get_corrected_position(pos, margin)\r\n        self.odometry.set_position(pos - self.start_pos)\r\n        self.odometry.set_encoders(0, 0)\r\n        self.odometry.set_front_distance(None)\r\n        self.pos = self.odometry.get_position()\r\n        self.is_saving_gps_samples = False\r\n        self.same_position_counter = 0\r\n\r\n    def raw_step(self):\r\n        """Raw step without odometry update. Used only for initialization."""\r\n        self.update_stuck_counter()\r\n        for callback in self.step_callbacks:\r\n            callback()\r\n        result = self.robot.step(TIME_STEP) != -1\r\n        self._lidar_image_cache = None\r\n        return result\r\n\r\n    def to_dict(self):\r\n        """Returns the robot\'s current state as a dictionary."""\r\n        return {\r\n            "position": self.get_position(),\r\n            "rotation": self.get_rotation(),\r\n        }\r\n\r\n    def on_step(self, callback):\r\n        """Registers a callback to be called on each step."""\r\n        self.step_callbacks.append(callback)\r\n\r\n    def extract_stack(self):\r\n        """Extracts the current call stack."""\r\n        call_stack = traceback.extract_stack()\r\n        functions = ""\r\n        idx = 0\r\n        for frame_summary in call_stack[2:-2]:\r\n            if idx > 0:\r\n                functions += "/"\r\n            functions += (frame_summary.name)\r\n            idx += 1\r\n\r\n        with open("steps.txt", "a", encoding="utf-8") as f:\r\n            f.write(functions + "\\n")\r\n\r\n    def step(self):\r\n        """Performs a single step of the robot\'s operation."""\r\n        self.step_counter += 1\r\n\r\n        self.is_lop = False\r\n        if self.receiver.getQueueLength() > 0:\r\n            message = self.receiver.getBytes()\r\n            if message[0] == ord(\'L\'):\r\n                print(f"Received LoP message in robot step!!")\r\n                # utils.log_debug(f"Received LoP message in robot step!!")\r\n                self.is_lop = True\r\n                self.set_corrected_position_by_lop(self.get_absolute_position(), 0.06)\r\n\r\n        self.update_odometry()\r\n        self.update_stuck_counter()\r\n        \r\n        if not self.is_saving_gps_samples and self.is_the_same_position:\r\n            self.is_saving_gps_samples = True\r\n        elif self.is_saving_gps_samples and (not self.is_the_same_position) or (self.same_position_counter >= LIMIT_AVERAGE):\r\n            x = [pos.x for pos in self.gps_pos[:self.same_position_counter]]\r\n            y = [pos.y for pos in self.gps_pos[:self.same_position_counter]]\r\n            self.odometry.set_position(Vector(np.mean(x), np.mean(y)))\r\n            # utils.log_debug(f"Calculated average GPS position: {self.odometry.get_position()} based on {self.same_position_counter} samples")\r\n            self.is_saving_gps_samples = False\r\n            self.same_position_counter = 0\r\n        \r\n        if self.is_saving_gps_samples and self.same_position_counter < LIMIT_AVERAGE:\r\n            self.gps_pos[self.same_position_counter] = self.gps_relative_position()\r\n            self.same_position_counter += 1\r\n\r\n        # print(f"Is robot in LoP? {self.is_lop}")\r\n        if DEBUGGPSOK:\r\n            est = self.get_position()\r\n            real = self.gps_ok_relative_position()\r\n            diff_x = abs(est.x - real.x)\r\n            diff_y = abs(est.y - real.y)\r\n            self.max_diff_x = max(self.max_diff_x, diff_x)\r\n            self.max_diff_y = max(self.max_diff_y, diff_y)\r\n            # print(f"Dif X: {diff_x:.4f}  Y: {diff_y:.4f}  |  Max X: {self.max_diff_x:.4f}  Max Y: {self.max_diff_y:.4f}")\r\n        for callback in self.step_callbacks:\r\n            callback()\r\n        result = self.robot.step(TIME_STEP) != -1\r\n        self._lidar_image_cache = None\r\n        return result\r\n\r\n    def update_stuck_counter(self):\r\n        """Updates the counter that tracks how many consecutive steps the robot has been stuck (not moving)."""\r\n        if self.start_pos == None: return\r\n        if not self.is_moving:\r\n            self.stuck_counter = 0\r\n            return\r\n\r\n        current_pos = self.get_position()\r\n        vel = current_pos - self.previous_position\r\n\r\n        current_dir = self.get_forward_vector()\r\n        vang = current_dir.angle_to(self.previous_direction)\r\n\r\n        # print(f"Vector length: {vel.length()}")\r\n        if vel.length() < 0.0005 and vang < 0.001:\r\n            self.stuck_counter += 1\r\n        else:\r\n            self.stuck_counter = 0\r\n\r\n        self.previous_position = current_pos\r\n        self.previous_direction = current_dir\r\n\r\n    def is_stuck(self, step_threshold=LIMIT_STEPS):\r\n        """Checks if the robot is stuck based on the stuck counter and a step threshold."""\r\n        return self.stuck_counter > step_threshold\r\n\r\n    def delay(self, ms):\r\n        """Delays the robot\'s operation for a given number of milliseconds."""\r\n        init_time = self.robot.getTime()\r\n        while self.step():\r\n            if (self.robot.getTime() - init_time) * 1000.0 >= ms:\r\n                break\r\n\r\n    def set_velocity(self, l, r):\r\n        """Sets the velocity of the robot\'s wheels and updates the robot\'s movement state."""\r\n        self.wheel_left.setVelocity(utils.clamp(l, -MAX_VEL, MAX_VEL))\r\n        self.wheel_right.setVelocity(utils.clamp(r, -MAX_VEL, MAX_VEL))\r\n        if l == 0 and r == 0:\r\n            self.stuck_counter = 0\r\n            self.is_moving = False\r\n        else:\r\n            self.is_moving = True\r\n\r\n        if l == r:\r\n            self.is_rotating = False\r\n        else:\r\n            self.is_rotating = True\r\n\r\n        if (l==-r):\r\n            self.is_the_same_position=True\r\n        else:\r\n            self.is_the_same_position=False\r\n        \r\n    def stop(self):\r\n        """Stops the robot\'s movement by setting both wheel velocities to zero."""\r\n        self.set_velocity(0, 0)\r\n\r\n    def get_lidar_image(self):\r\n        """Returns the cached lidar image if available; otherwise, retrieves it from the lidar sensor."""\r\n        if self._lidar_image_cache is None:\r\n            image = self.lidar.getRangeImage()\r\n            self._lidar_image_cache = image[1024:1536]\r\n        return self._lidar_image_cache\r\n\r\n    def get_lidar_points(self):\r\n        """Returns the lidar\'s distance collision points as world coordinates (Vectors)."""\r\n        roll, pitch, _ = self.imu.getRollPitchYaw()\r\n        if abs(roll) > 0.01 or abs(pitch) > 0.01:\r\n            return []\r\n\r\n        distances = np.array(self.get_lidar_image(), dtype=np.float32)\r\n\r\n        # Ray 0 points opposite to forward; rays increase clockwise (delta = -2\xcf\x80/512)\r\n        base_angle = self.get_forward_vector().angle() + math.pi\r\n        angles = base_angle + np.arange(512, dtype=np.float32) * (-2.0 * math.pi / 512)\r\n\r\n        valid = distances != np.inf\r\n        d = distances[valid]\r\n        a = angles[valid]\r\n\r\n        xs = np.sin(-a) * d   # Vector.from_angle uses sin(-angle) for x\r\n        ys = -np.cos(a) * d   # and -cos(angle) for y\r\n\r\n        return [Vector(float(xs[i]), float(ys[i])) for i in range(len(d))]\r\n\r\n    def update_odometry(self):\r\n        """Updates the robot\'s odometry based on lidar and encoders readings."""\r\n        # print(f"Updating odometry with pos: {self.get_position()}")\r\n        yaw = self.get_rotation()\r\n        front_ray = Side.FRONT.value\r\n        front_dist = min(min(self.get_lidar_image()[front_ray - 64: front_ray + 64]), 1.1) # NOTE: Used min function in case lidar dist = inf\r\n        # (max lidar dist: 1).\r\n\r\n        if self.first_update:\r\n            self.odometry.set_base_distances(front_dist)\r\n            print(f"First update - setting base front distance: {front_dist}")\r\n            self.first_update = False\r\n        # print(f"Updating odometry with front distance: {front_dist} and yaw: {yaw}")    \r\n        self.odometry.set_encoders(self.enc_left.getValue(), self.enc_right.getValue())\r\n        self.odometry.set_gps(self.gps_relative_position())\r\n        self.odometry.update(front_dist, yaw, self.get_position(), self.is_rotating)\r\n        self.pos = self.odometry.get_position()\r\n\r\n    def get_position(self):\r\n        """Returns the robot\'s current position as a Vector, relative to the starting position."""\r\n        return self.odometry.get_position() # pos\r\n    \r\n    def gps_relative_position(self):\r\n        """Returns the robot\'s GPS (noisy) position as a Vector, relative to the starting position."""\r\n        abs_pos = self.get_absolute_position()\r\n        if abs_pos is None or self.start_pos is None:\r\n            return Vector.ZERO\r\n        return abs_pos - self.start_pos\r\n    \r\n    def get_absolute_position(self):\r\n        """Returns the robot\'s GPS (noisy) absolute position as a Vector."""\r\n        x, z, y = self.gps.getValues()\r\n        return Vector(x, y)\r\n\r\n    def gps_ok_relative_position(self): # TODO (Martu): Delete...\r\n        if not DEBUGGPSOK or self.gps_ok is None:\r\n            return Vector.ZERO\r\n        x, z, y = self.gps_ok.getValues()\r\n        abs_pos = Vector(x, y)\r\n        if self.start_pos is None:\r\n            return Vector.ZERO\r\n        return abs_pos - self.start_pos\r\n\r\n    def get_rotation(self):\r\n        """Returns the robot\'s current rotation (yaw) in radians."""\r\n        roll, pitch, yaw = self.imu.getRollPitchYaw()\r\n        return yaw\r\n\r\n    def convert_camera(self, img, height, width):\r\n        """Converts the camera image from a byte buffer to a numpy array with shape (height, width, 4)."""\r\n        converted_image = np.array(np.frombuffer(img, np.uint8).reshape((height, width, 4)))\r\n        return converted_image\r\n\r\n    def get_camera_from_side(self, side):\r\n        """Returns the camera image from the specified side (LEFT, RIGHT, FRONT) as a numpy array."""\r\n        if side == Side.LEFT:\r\n            camera = self.left_camera\r\n        else:\r\n            if side == Side.RIGHT:\r\n                camera = self.right_camera\r\n            else:\r\n                camera = self.front_camera\r\n        return self.convert_camera(camera.getImage(), 40, 40)\r\n\r\n    def get_forward_vector(self):\r\n        """Returns the robot\'s forward direction as a unit vector."""\r\n        return Vector.from_angle(self.get_rotation())\r\n\r\n    def look_at(self, direction, margin=0.001, *, blocking_steps=-1):\r\n        """Rotates the robot to look at a specific direction (Vector) within a given margin."""\r\n        # print(f"Looking at {direction} with margin {margin} and blocking_steps {blocking_steps}")\r\n        is_done = False\r\n        steps = 0\r\n        while not self.is_stuck() and not self.is_lop:\r\n            angle = self.get_forward_vector().angle_to(direction)\r\n            if abs(angle) < margin:\r\n                is_done = True\r\n                self.stop()\r\n                break\r\n\r\n            vel = MAX_VEL / 0.25 * abs(angle)\r\n            if angle < 0:\r\n                self.set_velocity(vel, -vel)\r\n            else:\r\n                self.set_velocity(-vel, vel)\r\n\r\n            if blocking_steps == steps:\r\n                break\r\n\r\n            if not self.step():\r\n                break\r\n\r\n            steps += 1\r\n\r\n        return is_done\r\n\r\n    def turn(self, angle, margin=0.001, *, blocking_steps=-1):\r\n        """ Rotates the robot by a specific angle (in radians) within a given margin."""\r\n        # print(f"Robot state: turning!")\r\n        target = self.get_forward_vector().rotated(angle)\r\n        return self.look_at(target, margin, blocking_steps=blocking_steps)\r\n\r\n    def advance(self, distance, margin=0.001, *, blocking_steps=-1):\r\n        """Moves the robot forward or backward by a specific distance (in meters) within a given margin."""\r\n        initial_pos = self.get_position()\r\n        # print(f"Initial pos before advance loop: {initial_pos}")\r\n        is_done = False\r\n        steps = 0\r\n        while not self.is_stuck() and not self.is_lop:\r\n            traveled_dist = self.get_position().distance_to(initial_pos)\r\n            diff = abs(distance) - traveled_dist\r\n            if diff <= margin:\r\n                is_done = True\r\n                self.stop()\r\n                break\r\n\r\n            vel = min(max(diff/0.01, 0.1), 1) * MAX_VEL\r\n            if distance < 0: vel *= -1\r\n\r\n            if vel > 0:\r\n                front_rays = self.get_lidar_image()[Side.FRONT.value-45:Side.FRONT.value+45]\r\n                if min(front_rays) < 0.044:  # If we are very close to the wall, exit the while loop to avoid collision\r\n                    self.stop()\r\n                    print("Stopping advance to avoid collision with wall in front")\r\n                    break\r\n            else:\r\n                back_rays = self.get_lidar_image()[Side.BACK.value:Side.BACK.value+45] + self.get_lidar_image()[Side.BACK.value+467:Side.BACK.value+512]\r\n                if min(back_rays) < 0.044:  # If we are very close to the wall, exit the while loop to avoid collision\r\n                    self.stop()\r\n                    print("Stopping advance to avoid collision with wall in back")\r\n                    break\r\n\r\n            self.set_velocity(vel, vel)\r\n\r\n            if blocking_steps == steps:\r\n                break\r\n            if not self.step():\r\n                break\r\n\r\n            steps += 1\r\n\r\n        return is_done\r\n    \r\n    def move_to_point(self, target, margin=0.001, *, blocking_steps=-1):\r\n        """Moves the robot to a specific point (Vector) within a given margin without making curved movements."""\r\n        ANGLE_MIN = math.pi / 42\r\n\r\n        is_done = False\r\n        steps = 0\r\n        while not self.is_stuck() and not self.is_lop:\r\n            position = self.get_position()\r\n            dist = position.distance_to(target)\r\n\r\n            if dist < margin:\r\n                is_done = True\r\n                self.stop()\r\n                break\r\n\r\n            angle = self.get_forward_vector().angle_to(target - position)\r\n            # print(f"Angle to target: {math.degrees(angle)} degrees")\r\n\r\n            if abs(angle) < ANGLE_MIN:\r\n                self.set_velocity(MAX_VEL, MAX_VEL)\r\n                self.is_rotating = False\r\n            else:\r\n                # Proportional control for turning speed based on the angle to the target\r\n                turn_vel = utils.clamp(abs(angle) / (math.pi / 4) * MAX_VEL, MAX_VEL * 0.3, MAX_VEL)\r\n                if angle < 0:\r\n                    self.set_velocity(turn_vel, -turn_vel)\r\n                else:\r\n                    self.set_velocity(-turn_vel, turn_vel)\r\n                self.is_rotating = True\r\n            # print(f"Is robot rotating? {self.is_rotating}")\r\n            if blocking_steps == steps:\r\n                break\r\n            if not self.step():\r\n                break\r\n\r\n            steps += 1\r\n\r\n        return is_done\r\n    ')
    __stickytape_write_module('utils.py', b'import math\r\nimport numpy as np\r\nfrom typing import Dict\r\nfrom vector import Vector\r\n\r\nimport logging\r\n# logger = logging.getLogger("willow")\r\n# filename = \'willow.log\'\r\n\r\n# logging.basicConfig(filename=filename, encoding=\'utf-8\', level=logging.DEBUG)\r\n\r\nlogger = logging.getLogger("willow")\r\nlogger.setLevel(logging.DEBUG)\r\n\r\nif not logger.handlers:\r\n    handler = logging.FileHandler("willow.log", encoding="utf-8")\r\n    formatter = logging.Formatter(\'%(asctime)s - %(levelname)s - %(message)s\')\r\n    handler.setFormatter(formatter)\r\n    logger.addHandler(handler)\r\n\r\nlogger.propagate = False\r\n\r\ndef create_csv(filename, headers):\r\n    with open(filename, \'w\') as f:\r\n        f.write(headers + \'\\n\')\r\n\r\ndef write_csv(filename, data):\r\n    with open(filename, \'a\') as f:\r\n        f.write(\';\'.join(str(x) for x in data) + \'\\n\')\r\n\r\ndef log_debug(msg):\r\n    # print(msg)\r\n    # return\r\n    logger.debug(msg)\r\n\r\ndef clamp(val, min_val, max_val, print_val=False):\r\n    if print_val:\r\n        print(f"Clamping value: {val} to range ({min_val}, {max_val})")\r\n    if val < min_val: \r\n        if print_val:\r\n            print(f"Value {val} is less than min_val {min_val}, clamping to min_val")\r\n        return min_val\r\n    if val > max_val: \r\n        if print_val:\r\n            print(f"Value {val} is greater than max_val {max_val}, clamping to max_val")\r\n        return max_val\r\n    return val\r\n\r\ndef point_on_horizontal_border(robot_position, tolerance = 0.009):\r\n    aux = robot_position.y - 0.06\r\n    # print(f"Checking horizontal border: robot_position.y={robot_position.y}, aux={aux}, tolerance={tolerance}")\r\n    if near_multiple(aux, 0.12, tolerance):\r\n        # print(f"Point {robot_position} is on horizontal border")\r\n        return True\r\n    return False\r\n \r\ndef point_on_vertical_border(robot_position, tolerance = 0.009):\r\n    aux = robot_position.x - 0.06\r\n    if near_multiple(aux, 0.12, tolerance):\r\n        # print(f"Point {robot_position} is on vertical border")\r\n        return True\r\n    return False\r\n\r\ndef near_multiple(num, base = 0.12, tolerance = 1e-6):\r\n    # Encuentra el m\xc3\xbaltiplo m\xc3\xa1s cercano de la base\r\n    closest_multiple = round(num / base) * base\r\n    # Verifica si la diferencia es menor que la tolerancia\r\n    # print(f"Checking if {num} is near multiple of {base}, difference={abs(num - closest_multiple)}, tolerance={tolerance}")\r\n    # print("-"*20)\r\n    return abs(num - closest_multiple) < tolerance\r\n\r\ndef sort_cw(list_points):\r\n    list_aux = list_points.copy()\r\n    # Ordena los puntos en sentido horario\r\n    aux=[]\r\n    sum_min = 1000\r\n    first = 0\r\n    for i in range(4):\r\n        sum_points = list_aux[i][0] + list_aux[i][1]\r\n        if sum_points < sum_min:\r\n            sum_min = sum_points\r\n            first = i\r\n    # remove an element of numpy array\r\n    pos_1 = list_aux[first]\r\n    list_aux = np.delete(list_aux, first, axis=0)\r\n\r\n    sum_max =- 10000\r\n    third = 0\r\n    for i in range(3):\r\n        sum_points = list_aux[i][0] + list_aux[i][1]\r\n        if sum_points > sum_max:\r\n            sum_max = sum_points\r\n            third = i\r\n    pos_3 = list_aux[third]\r\n    list_aux = np.delete(list_aux, third, axis=0)\r\n\r\n    if list_aux[0][0] > list_aux[1][0]:\r\n        pos_2 = list_aux[0]\r\n        pos_4 = list_aux[1]\r\n    else:\r\n        pos_2 = list_aux[1]\r\n        pos_4 = list_aux[0]\r\n    return np.array([pos_1, pos_2, pos_3, pos_4], dtype = np.float32)\r\n\r\ndef get_target_contour(contours, hierarchy, is_letter_contour = False):\r\n    hierarchy = hierarchy[0]\r\n    for component in zip(contours, hierarchy):\r\n        current_contour = component[0]\r\n        current_hierarchy = component[1]            \r\n        if not is_letter_contour:\r\n            if current_hierarchy[2] >= 0:\r\n                contour = current_contour\r\n                return contour\r\n        else:\r\n            if current_hierarchy[2] < 0 and current_hierarchy[3] >= 0:\r\n                contour = current_contour\r\n                return contour\r\n    return None\r\n\r\ndef get_percentage(a, b):\r\n    total = a + b\r\n    if total == 0: return None, None\r\n    a_percentage = round((a / total) * 100)\r\n    b_percentage = round((b / total) * 100)\r\n    return a_percentage, b_percentage\r\n\r\ndef get_vectors_average(vectors):\r\n    if len(vectors) == 0: return None\r\n    sum_vector = Vector(0, 0)\r\n    for vector in vectors:\r\n        sum_vector += vector\r\n    average_vector = sum_vector / len(vectors)\r\n    return average_vector\r\n\r\ndef get_nearest_multiple(num, mult = 0.06):\r\n    return round(num / mult) * mult\r\n\r\ndef wrap_to_pi(angle: float) -> float:\r\n    """Envuelve un \xc3\xa1ngulo a (-pi, pi]."""\r\n    return (angle + math.pi) % (2.0 * math.pi) - math.pi\r\n\r\ndef cardinal_ray_indices(theta: float,\r\n                         N: int = 512,\r\n                         lidar_offset: float = 0.0):\r\n    """\r\n    Devuelve los \xc3\xadndices de rayo (0..N-1) que apuntan a los ejes cardinales del mundo\r\n    (arriba, abajo, izquierda, derecha), dados:\r\n      - theta: orientaci\xc3\xb3n del robot en rad (0 hacia arriba, +CCW, -CW),\r\n      - N: cantidad de rayos del LiDAR (por defecto 512),\r\n      - lidar_offset: desfase del LiDAR respecto al chasis (rad). Por defecto 0,\r\n        asumiendo que el rayo 0 est\xc3\xa1 exactamente hacia atr\xc3\xa1s del robot.\r\n\r\n    Convenciones del LiDAR:\r\n      - \xc3\x8dndices 0..N-1, crecen en sentido horario (CW).\r\n      - El rayo 0 (y N-1) apuntan hacia atr\xc3\xa1s del robot.\r\n\r\n    Retorna: dict con claves \'arriba\', \'abajo\', \'izquierda\', \'derecha\'.\r\n    """\r\n    delta = 2.0 * math.pi / N\r\n\r\n    def angle_to_index_world(alpha_world: float) -> int:\r\n        # Pasar el \xc3\xa1ngulo del mundo al marco del robot\r\n        alpha_body = wrap_to_pi(alpha_world - theta)\r\n        # Invertir la parametrizaci\xc3\xb3n del LiDAR para hallar el \xc3\xadndice m\xc3\xa1s cercano\r\n        idx_float = (math.pi + lidar_offset - alpha_body) / delta\r\n        # print(f"Idx not rounded: {idx_float}")\r\n        # idx = int(round(idx_float)) % N\r\n        return idx_float % N\r\n\r\n    arriba = angle_to_index_world(0.0)\r\n    abajo  = angle_to_index_world(math.pi)      # (\xcf\x80 \xe2\x89\xa1 -\xcf\x80)\r\n    derecha = angle_to_index_world(-math.pi/2)  # CW\r\n    izquierda = angle_to_index_world( math.pi/2) # CCW\r\n\r\n    return arriba, abajo, izquierda, derecha\r\n\r\ndef order_nearest_points(points, reference):\r\n    points.sort(key=lambda p: abs(reference - p))\r\n    return points\r\n\r\ndef get_prev_follow_index(current, total = 512):\r\n    if current - int(current) > 0.001:\r\n        prev = int(current)\r\n        following = (int(current) + 1) % total\r\n    else:\r\n        prev = following = int(current)\r\n    return prev, following\r\n\r\ndef get_corrected_position(pos, margin):\r\n    if pos is None: return\r\n    pos.x = get_nearest_multiple(pos.x, margin)\r\n    pos.y = get_nearest_multiple(pos.y, margin)\r\n    return Vector(pos.x, pos.y)')
    __stickytape_write_module('vector.py', b'import math \r\n\r\nclass Vector:\r\n    @staticmethod\r\n    def from_tuple(tuple):\r\n        return Vector(tuple[0], tuple[1])\r\n    \r\n    @staticmethod\r\n    def from_angle(angle, length = 1):\r\n        x = math.sin(-angle)\r\n        y = math.cos(angle)\r\n        return Vector(x, -y) * length\r\n    \r\n    def __init__ (self, x, y):\r\n        self.x = x\r\n        self.y = y\r\n        \r\n    def distance_to(self, another_vector):\r\n        v1 = another_vector.x - self.x\r\n        v2 = another_vector.y - self.y\r\n        dist = v1**2 + v2**2\r\n        answer = math.sqrt(dist)\r\n        return answer\r\n    \r\n    def normalized(self):\r\n        x = self.x\r\n        y = self.y\r\n        l = x*x+y*y\r\n        if l != 0:\r\n            l = math.sqrt(l)\r\n            x /= l\r\n            y /= l\r\n        return Vector(x, y)\r\n\r\n    def length(self):\r\n        x = self.x\r\n        y = self.y\r\n        return math.sqrt(x*x + y*y)\r\n\r\n    def angle(self):\r\n        return math.atan2(-self.x, -self.y)\r\n\r\n    def angle_to(self, another_vector):\r\n        a = another_vector.cross(self)\r\n        b = another_vector.dot(self)\r\n        return math.atan2(a, b)\r\n    \r\n    def cross(self, another_vector):\r\n        return self.x * another_vector.y - self.y * another_vector.x\r\n    \r\n    def dot(self, another_vector):\r\n        return self.x * another_vector.x + self.y * another_vector.y\r\n    \r\n    def rotated(self, radians):\r\n        a = self.angle() + radians\r\n        l = self.length()\r\n        v = Vector.from_angle(a)\r\n        result = v * l\r\n        return result\r\n    \r\n    def round(self):\r\n        return Vector(round(self.x), round(self.y))\r\n    \r\n    def floor(self):\r\n        return Vector(math.floor(self.x), math.floor(self.y))\r\n    \r\n    def get_opposite(self):\r\n        return self.rotated(math.pi)\r\n\r\n    def __add__(self, vector):\r\n        return Vector(self.x + vector.x, self.y + vector.y)\r\n    \r\n    def __sub__(self, vector):\r\n        return Vector(self.x - vector.x, self.y - vector.y)\r\n\r\n    def __mul__(self, scalar):\r\n        return Vector(self.x * scalar, self.y * scalar)\r\n    \r\n    def __rmul__(self, scalar):\r\n        return self*scalar\r\n    \r\n    def __truediv__(self, scalar):\r\n        return Vector(self.x / scalar, self.y / scalar)\r\n    \r\n    def __repr__(self):\r\n        return f"Vector({self.x}, {self.y})"\r\n    \r\n    def __eq__(self, value):\r\n        if value is None: return False\r\n        if not isinstance(value, Vector): return False\r\n        return self.x == value.x and self.y == value.y\r\n    \r\n    def __hash__(self):\r\n        key = (self.x, self.y)\r\n        return hash(key)\r\n\r\nVector.UP = Vector(0, -1)\r\nVector.DOWN = Vector(0, 1)\r\nVector.LEFT = Vector(-1, 0)\r\nVector.RIGHT = Vector(1, 0)\r\nVector.ONE = Vector(1, 1)\r\nVector.ZERO = Vector(0, 0)\r\n')
    __stickytape_write_module('side.py', b'from enum import Enum\r\nimport math\r\n\r\nclass Side(Enum):\r\n    LEFT = 128\r\n    RIGHT = 384\r\n    FRONT = 256\r\n    BACK = 0\r\n\r\n    def get_angle(self):\r\n        if self == Side.LEFT:\r\n            return math.pi/2\r\n        elif self == Side.RIGHT:\r\n            return -math.pi/2\r\n        return 0')
    __stickytape_write_module('filter.py', b'import math\r\nimport utils\r\nfrom vector import Vector\r\n\r\nROT_MARGIN = math.pi/20\r\nMAX_STEP_T = 0.04\r\nMAX_TRASLATION_PER_STEP = 0.002\r\nROBOT_RADIUS = 0.035\r\n\r\nclass LidarPositioner:\r\n    def __init__(self, init_pos = Vector(0, 0)):\r\n        # self.starting_point = Vector(0, 0)\r\n        \r\n        self.base_fw_dist = -1\r\n        self.base_bw_dist = -1\r\n        self.base_rt_dist = -1\r\n        self.base_lt_dist = -1\r\n\r\n        self._pos = init_pos\r\n        self.last_rot = None\r\n\r\n    def set_base_distances(self, fw_dist, bw_dist, rt_dist, lt_dist):\r\n        self.base_fw_dist = fw_dist\r\n        self.base_bw_dist = bw_dist\r\n        self.base_rt_dist = rt_dist\r\n        self.base_lt_dist = lt_dist\r\n\r\n    def update_starting_point(self, point):\r\n        return\r\n        self.starting_point = point\r\n\r\n    def get_base_distances(self):\r\n        return self.base_fw_dist, self.base_bw_dist, self.base_rt_dist, self.base_lt_dist\r\n\r\n    def calculate_y_translation(self, fw_dist, bw_dist):\r\n        if self.base_fw_dist == -1 or self.base_bw_dist == -1:\r\n            # print(f"Base distances not set for Y translation: FW: {self.base_fw_dist}, BW: {self.base_bw_dist}")\r\n            return 0\r\n        # print(f"Base distances for Y translation: FW: {self.base_fw_dist}, BW: {self.base_bw_dist}")\r\n        # print(f"Current distances for Y translation: FW: {fw_dist}, BW: {bw_dist}")\r\n        # print(f"FW distance: {fw_dist} - BW distance: {bw_dist} - Base FW distance: {self.base_fw_dist} - Base BW distance: {self.base_bw_dist}")\r\n        fw_diff = fw_dist - self.base_fw_dist\r\n        bw_diff = bw_dist - self.base_bw_dist\r\n        # print(f"Distance differences for Y translation: FW diff: {fw_diff}, BW diff: {bw_diff}")\r\n        if abs(fw_diff) > MAX_STEP_T and abs(bw_diff) > MAX_STEP_T:\r\n            print(f"Enormous distance differences for Y translation: FW diff: {fw_diff}, BW diff: {bw_diff}")\r\n            print(f"Suppoused to return 0 for Y translation")\r\n            return 0\r\n\r\n        if abs(bw_diff) > MAX_STEP_T:\r\n            print(f"Significant distance difference for Y translation: FW diff: {fw_diff}, BW diff: {bw_diff}")\r\n            print(f"Suppoused to return {fw_diff} for Y translation")\r\n            return -fw_diff\r\n        \r\n        if abs(bw_dist) == 1:\r\n            print(f"BW distance is 1, using FW diff for Y translation: {fw_diff}")\r\n            return -fw_diff\r\n        \r\n        return bw_diff\r\n    \r\n    def calculate_x_translation(self, rt_dist, lt_dist):\r\n        if self.base_rt_dist == -1 or self.base_lt_dist == -1:\r\n            return 0\r\n        rt_diff = rt_dist - self.base_rt_dist\r\n        # print(f"Base distances for X translation: RT: {self.base_rt_dist}, LT: {self.base_lt_dist}")\r\n        # print(f"Current distances for X translation: RT: {rt_dist}, LT: {lt_dist}")\r\n        lt_diff = lt_dist - self.base_lt_dist\r\n        # print(f"Distance differences for X translation: RT diff: {rt_diff:.5f}, LT diff: {lt_diff:.5f}")\r\n        if abs(rt_diff) > MAX_STEP_T and abs(lt_diff) > MAX_STEP_T:\r\n            print(f"Enormous distance differences for X translation: RT diff: {rt_diff:.5f}, LT diff: {lt_diff:.5f}")\r\n            print(f"Suppoused to return 0 for X translation")\r\n            return 0\r\n        \r\n        if abs(rt_diff) > MAX_STEP_T:\r\n            print(f"Significant distance difference for X translation: RT diff: {rt_diff:.5f}, LT diff: {lt_diff:.5f}")\r\n            print(f"Suppoused to return {lt_diff:.5f} for X translation")\r\n            return -lt_diff\r\n        \r\n        if abs(rt_diff) == 1:\r\n            print(f"RT distance is 1, using LT diff for X translation: {lt_diff:.5f}")\r\n            return -lt_diff\r\n\r\n        return rt_diff\r\n\r\n    def update(self, fw_dist, bw_dist, rt_dist, lt_dist, rot, pos):\r\n        if self.last_rot is None:\r\n            self.last_rot = rot\r\n        rot_diff = rot - self.last_rot\r\n        if True:\r\n            # print(f"Rot diff: {rot_diff:.5f} within margin, updating position")\r\n            x_translation = self.calculate_x_translation(rt_dist, lt_dist)\r\n            y_translation = self.calculate_y_translation(fw_dist, bw_dist)\r\n            # print(f"Calculated translations: X: {x_translation:.5f}, Y: {y_translation:.5f}")\r\n            self._pos = Vector(pos.x - x_translation, pos.y - y_translation)\r\n            self.last_rot = rot\r\n            self.set_base_distances(fw_dist, bw_dist, rt_dist, lt_dist)\r\n            return True\r\n        return False\r\n    \r\n    def get_position(self):\r\n        return self._pos\r\n\r\nclass FrontLidarPositioner:\r\n    def __init__(self, init_pos = Vector(0, 0)):\r\n        # self.starting_point = Vector(0, 0)\r\n        \r\n        self.base_front_dist = -1\r\n        \r\n\r\n        self._pos = init_pos\r\n        self.last_rot = None\r\n\r\n    def set_base_distances(self, front_dist):\r\n        self.base_front_dist = front_dist\r\n\r\n    def set_encoders(self, left, right):\r\n        return\r\n    \r\n    def set_gps(self, gps_pos):\r\n        return\r\n    \r\n    def update_starting_point(self, point):\r\n        return\r\n        self.starting_point = point\r\n\r\n    def get_base_distances(self):\r\n        return self.base_front_dist\r\n\r\n    def calculate_translation(self, front_dist, actual_rot):\r\n        # print(f"Calculating translation with front_dist: {front_dist}, actual_rot: {actual_rot}")\r\n        if self.base_front_dist == -1:\r\n            # print(f"Base distances not set for Y translation: FW: {self.base_fw_dist}, BW: {self.base_bw_dist}")\r\n            return Vector(0, 0)\r\n        # print(f"Base distances for Y translation: FW: {self.base_fw_dist}, BW: {self.base_bw_dist}")\r\n        # print(f"Current distances for Y translation: FW: {fw_dist}, BW: {bw_dist}")\r\n        # print(f"FW distance: {fw_dist} - BW distance: {bw_dist} - Base FW distance: {self.base_fw_dist} - Base BW distance: {self.base_bw_dist}")\r\n        front_diff = front_dist - self.base_front_dist\r\n  \r\n        # print(f"Distance differences for Y translation: FW diff: {fw_diff}, BW diff: {bw_diff}")\r\n        # print(f"Distance difference for Y translation: Front diff: {front_diff}")\r\n        if front_diff == None:\r\n            print(f"Front distance is None, returning 0 translation")\r\n        if abs(front_diff) > MAX_STEP_T:\r\n            print(f"Enormous distance differences for Y translation: FW diff: {front_diff}")\r\n            print(f"Suppoused to return 0 for translation")\r\n            return Vector(0, 0)\r\n\r\n        # Teniendo el \xc3\xa1ngulo actual, podemos calcular la componente en X e Y del movimiento\r\n        x_translation = -front_diff * math.sin(actual_rot)\r\n        y_translation = -front_diff * math.cos(actual_rot)\r\n        # print(f"Calculated translation components before clamping: X: {x_translation}, Y: {y_translation}")\r\n        \r\n        # clamped_x_translation = utils.clamp(x_translation, -MAX_TRASLATION_PER_STEP * math.sin(actual_rot), MAX_TRASLATION_PER_STEP * math.sin(actual_rot))\r\n        # clamped_y_translation = utils.clamp(y_translation, MAX_TRASLATION_PER_STEP * math.cos(actual_rot), -MAX_TRASLATION_PER_STEP * math.cos(actual_rot))\r\n\r\n        x_limit = -MAX_TRASLATION_PER_STEP * math.sin(actual_rot)\r\n        y_limit = -MAX_TRASLATION_PER_STEP * math.cos(actual_rot)\r\n        # print(f"Limits -> X: {x_limit}, Y: {y_limit}")\r\n        # utils.log_debug(f"X limit: {x_limit}, Y limit: {y_limit}")\r\n\r\n        clamped_x_translation = utils.clamp(abs(x_translation), 0, abs(x_limit), False)\r\n        clamped_y_translation = utils.clamp(abs(y_translation), 0, abs(y_limit), False)\r\n\r\n        if x_translation < 0:\r\n            clamped_x_translation = -clamped_x_translation\r\n        if y_translation < 0:\r\n            clamped_y_translation = -clamped_y_translation\r\n        # print(f"Clamped X translation: {clamped_x_translation}, Clamped Y translation: {clamped_y_translation}")\r\n\r\n        # print(f"Clamped translation components: X: {clamped_x_translation}, Y: {clamped_y_translation}")\r\n        # utils.log_debug(f"Final X traslation: {clamped_x_translation}, Final Y translation: {clamped_y_translation}")\r\n\r\n        # print(f"X limit: {x_limit}, Y limit: {y_limit}")\r\n        # print(f"Calculated translation components before clamping: X: {x_translation}, Y: {y_translation} based on front diff: {front_diff} and actual rotation: {actual_rot}")\r\n        # print(f"Calculated translation components after clamping: X: {clamped_x_translation}, Y: {clamped_y_translation} based on front diff: {front_diff} and actual rotation: {actual_rot}")\r\n        # print(f"Calculated translation components: X: {x_translation:.10f}, Y: {y_translation:.5f} based on front diff: {front_diff:.5f} and actual rotation: {actual_rot:.10f}")\r\n        # if x_translation == \r\n\r\n        return Vector(clamped_x_translation, clamped_y_translation)\r\n\r\n    def update(self, front_dist, rot, ant_pos, is_rotating):\r\n        if is_rotating:\r\n            # print(f"Es la primera vez, distancia frontal: {front_dist:.5f}, rotaci\xc3\xb3n: {rot:.5f}, posici\xc3\xb3n anterior: X: {ant_pos.x:.5f}, Y: {ant_pos.y:.5f}")\r\n            # print(f"Rotating, updating base distances with front distance: {front_dist}")\r\n            self.set_base_distances(front_dist)\r\n            # print(f"Robot is rotating, not updating position but setting base front distance: {front_dist}")\r\n            return True\r\n        else:\r\n            # print(f"Rot diff: {rot_diff:.5f} within margin, updating position")\r\n            translation = self.calculate_translation(front_dist, rot)\r\n            # print(f"Calculated translation: X: {translation.x:.5f}, Y: {translation.y:.5f}")\r\n            self._pos = Vector(ant_pos.x - translation.x, ant_pos.y - translation.y)\r\n            # print(f"Ant position: X: {ant_pos.x:.5f}, Y: {ant_pos.y:.5f} - New position: X: {self._pos.x:.5f}, Y: {self._pos.y:.5f}")\r\n           \r\n            self.last_rot = rot\r\n            self.set_base_distances(front_dist)\r\n            return True\r\n    \r\n    def get_position(self):\r\n        return self._pos\r\n    \r\n    def set_position(self, pos):\r\n        self._pos = pos\r\n\r\n\r\n_ENC_WHEEL_RADIUS = 0.026\r\n_ENC_MAX_DISP     = 6.28 * _ENC_WHEEL_RADIUS * 0.016 * 1.1   # max desplazamiento por step (~3.1 mm)\r\n_ENC_GPS_ALPHA    = 0.12   # peso del GPS en la fusi\xc3\xb3n (12 % por step)\r\n_ENC_GPS_SMOOTH   = 0.30   # EMA alpha para suavizado GPS (ventana efectiva ~3 steps, 53 ms)\r\n_ENC_GPS_DEADBAND = 0.002  # error m\xc3\xadnimo para aplicar correcci\xc3\xb3n GPS (2 mm)\r\n_ENC_STUCK_MIN_DISP = 0.0010          # avance encoder m\xc3\xadnimo para considerar movimiento (1 mm)\r\n_ENC_STUCK_LIDAR_EPS = 0.00035        # cambio m\xc3\xadnimo de lidar frontal para validar avance (0.35 mm)\r\n_ENC_STUCK_CONSECUTIVE_STEPS = 4      # steps seguidos de mismatch para declarar trabado\r\n_ENC_UNSTUCK_CONSECUTIVE_STEPS = 2    # steps v\xc3\xa1lidos para salir de estado trabado\r\n\r\nclass EncoderPositioner:\r\n    def __init__(self, init_pos=Vector(0, 0)):\r\n        self._pos        = init_pos\r\n        self._prev_left  = None\r\n        self._prev_right = None\r\n        self._gps_smooth = None   # EMA del GPS\r\n        self._prev_front_dist = None\r\n        self._left_enc   = None\r\n        self._right_enc  = None\r\n        self._gps_pos    = None\r\n        self.last_rot    = None\r\n        self._stuck_counter = 0\r\n        self._unstuck_counter = 0\r\n        self._is_stuck_by_lidar = False\r\n\r\n    # --- setters de datos externos (llamar antes de update) ---\r\n\r\n    def set_encoders(self, left, right):\r\n        self._left_enc  = left\r\n        self._right_enc = right\r\n\r\n    def set_front_distance(self, front_dist):\r\n        self._prev_front_dist = front_dist\r\n\r\n    def set_gps(self, gps_pos):\r\n        self._gps_pos = gps_pos\r\n\r\n    # --- interfaz polim\xc3\xb3rfica con FrontLidarPositioner ---\r\n\r\n    def set_base_distances(self, front_dist):\r\n        pass  # no aplica a encoders\r\n\r\n    def update_starting_point(self, point):\r\n        return\r\n\r\n    def get_base_distances(self):\r\n        return None  # no aplica a encoders\r\n\r\n    def calculate_translation(self, front_dist, actual_rot):\r\n        return Vector(0, 0)  # no aplica a encoders\r\n\r\n    def update(self, front_dist, rot, ant_pos, is_rotating):\r\n       \r\n        # utils.log_debug(f"As\xc3\xad comienzo el update de EncoderPositioner: {self._pos}")\r\n        left_enc  = self._left_enc\r\n        right_enc = self._right_enc\r\n        gps_pos   = self._gps_pos\r\n        yaw       = rot\r\n\r\n        if left_enc is None or right_enc is None:\r\n            return True\r\n\r\n        # Primera llamada: solo guardar valores de referencia\r\n        if self._prev_left is None:\r\n            self._prev_left  = left_enc\r\n            self._prev_right = right_enc\r\n            self._prev_front_dist = front_dist\r\n            return True\r\n\r\n        delta_left  = (left_enc  - self._prev_left)  * _ENC_WHEEL_RADIUS\r\n        delta_right = (right_enc - self._prev_right) * _ENC_WHEEL_RADIUS\r\n        self._prev_left  = left_enc\r\n        self._prev_right = right_enc\r\n\r\n        if is_rotating:\r\n            self._prev_front_dist = front_dist\r\n            return True\r\n\r\n        d_center = (delta_left + delta_right) / 2.0\r\n        d_center = max(-_ENC_MAX_DISP, min(_ENC_MAX_DISP, d_center))\r\n\r\n        lidar_delta = 0.0\r\n        if front_dist is not None and self._prev_front_dist is not None:\r\n            lidar_delta = self._prev_front_dist - front_dist\r\n\r\n        # Si encoder indica avance pero lidar frontal no cambia acorde, marcamos posible trabado.\r\n        if abs(d_center) >= _ENC_STUCK_MIN_DISP and front_dist == 1.1:\r\n            self._stuck_counter += 1\r\n            self._unstuck_counter = 0\r\n        else:\r\n            self._unstuck_counter += 1\r\n            if self._stuck_counter > 0:\r\n                self._stuck_counter -= 1\r\n\r\n        if self._stuck_counter >= _ENC_STUCK_CONSECUTIVE_STEPS:\r\n            self._is_stuck_by_lidar = True\r\n\r\n        if self._is_stuck_by_lidar:\r\n            if self._unstuck_counter >= _ENC_UNSTUCK_CONSECUTIVE_STEPS:\r\n                self._is_stuck_by_lidar = False\r\n                self._stuck_counter = 0\r\n            else:\r\n                self._prev_front_dist = front_dist\r\n                self.last_rot = rot\r\n                return True\r\n\r\n        dx = -d_center * math.sin(yaw)\r\n        dy = -d_center * math.cos(yaw)\r\n        encoder_pos = Vector(self._pos.x + dx, self._pos.y + dy)\r\n\r\n        if gps_pos is not None:\r\n            if self._gps_smooth is None:\r\n                self._gps_smooth = gps_pos\r\n            else:\r\n                self._gps_smooth = Vector(\r\n                    _ENC_GPS_SMOOTH * gps_pos.x + (1 - _ENC_GPS_SMOOTH) * self._gps_smooth.x,\r\n                    _ENC_GPS_SMOOTH * gps_pos.y + (1 - _ENC_GPS_SMOOTH) * self._gps_smooth.y,\r\n                )\r\n            error = math.hypot(self._gps_smooth.x - encoder_pos.x, self._gps_smooth.y - encoder_pos.y)\r\n            if error > _ENC_GPS_DEADBAND:\r\n                self._pos = Vector(\r\n                    (1 - _ENC_GPS_ALPHA) * encoder_pos.x + _ENC_GPS_ALPHA * self._gps_smooth.x,\r\n                    (1 - _ENC_GPS_ALPHA) * encoder_pos.y + _ENC_GPS_ALPHA * self._gps_smooth.y,\r\n                )\r\n            else:\r\n                self._pos = encoder_pos\r\n        else:\r\n            self._pos = encoder_pos\r\n\r\n        self._prev_front_dist = front_dist\r\n        self.last_rot = rot\r\n        # utils.log_debug(f"As\xc3\xad termino el update de EncoderPositioner: {self._pos}")\r\n        return True\r\n\r\n    def get_position(self):\r\n        return self._pos\r\n\r\n    def set_position(self, pos):\r\n        self._pos = pos\r\n        self._gps_smooth = None')
    __stickytape_write_module('navigation/__init__.py', b'\n')
    __stickytape_write_module('navigation/navigator.py', b'from vector import Vector\r\nfrom collections import deque\r\nfrom heapq import heappush, heappop\r\nimport math\r\nimport utils\r\nfrom navigation.map import Map, MINITILE_SIZE_PX\r\n\r\nclass Navigator:\r\n    def __init__(self):\r\n        self.map = Map()\r\n\r\n        self.pixel_paths = {}\r\n\r\n        # These variables are just to send the visualizer\r\n        self.start = None\r\n        self.came_from = {}\r\n        self.cost_so_far = {}\r\n        self.penalty_scores = {}\r\n        self.priority_scores = {}\r\n        self.walls_around = {}\r\n        self.path = []\r\n    \r\n    def update(self, robot_position, lidar_points, surrounding_tiles):\r\n        self.map.update(robot_position, lidar_points, surrounding_tiles)\r\n\r\n    def find_closest_traversable_point(self, target, robot_pos, special_case=False):\r\n        """Finds the closest traversable point of a target world pos."""\r\n        return self.map.find_closest_traversable_point(target, robot_pos, special_case)\r\n    \r\n    def is_traversable(self, point):\r\n        """Checks if a point is traversable in the map."""\r\n        return self.map.is_traversable(point)\r\n\r\n    def mark_lop(self, position):\r\n        """Marks a lop point and invalidates pixel paths related to it."""\r\n        self.map.mark_lop(position)\r\n        self.invalidate_pixel_paths(position)\r\n\r\n    def mark_position_as_visited(self, position):\r\n        """Marks a position as visited in the map."""\r\n        self.map.mark_position_as_visited(position)\r\n\r\n    def mark_position_as_obstructed(self, position):\r\n        """Marks a position as obstructed in the map and invalidates pixel paths related to it."""\r\n        self.map.mark_as_obstructed(position)\r\n\r\n        # Invalidate all cached paths to the minitile at position\r\n        self.invalidate_pixel_paths(position)\r\n\r\n    def invalidate_pixel_paths(self, position):\r\n        """Invalidates all cached pixel paths that start or end in the minitile at position."""\r\n        minitile = self.map.world_to_minitile(position)\r\n        history_paths = self.pixel_paths.get((minitile.x, minitile.y))\r\n        if history_paths == None: return\r\n        history_paths.clear()\r\n    \r\n    def find_cached_pixel_path(self, src, dst):\r\n        """Checks if theres an already calculated pixel path from src to dst."""\r\n        history_paths = self.pixel_paths.get(dst)\r\n        if history_paths == None: return None\r\n        src_path = history_paths.get(src)\r\n        if src_path == None: return None\r\n        for p in src_path:\r\n            if not self.map.is_pixel_traversable(p):\r\n                history_paths[src] = None\r\n                return None\r\n        return src_path\r\n    \r\n    def store_pixel_path(self, src, dst, path):\r\n        """Stores a pixel path from src to dst in the cache."""\r\n        history_paths = self.pixel_paths.get(dst)\r\n        if history_paths == None:\r\n            self.pixel_paths[dst] = {src: path}\r\n        else: # Updates the path if it already exists a way of reaching dst\r\n            history_paths[src] = path\r\n\r\n    def calculate_cost_pixel_path(self, pixels):\r\n        """Calculates the cost of a pixel path based on distance."""\r\n        cost = 0\r\n        adicional_cost = 8\r\n        # consecutive_swamps = 0\r\n        for i in range(len(pixels) - 1): #NOTE: If we do not subtract, the b item will be out of range\r\n            a = pixels[i]\r\n            b = pixels[i+1]\r\n            cost += a.distance_to(b)\r\n            if self.map.is_pixel_swamp(b):\r\n                # consecutive_swamps += 1\r\n                # print(f"sumo 1")\r\n                cost += 8.0  # Penalty for swamp pixels\r\n                world_pixel = self.map.pixel_to_world(b)\r\n                minitile_pixel = self.map.world_to_minitile(world_pixel)\r\n                _, visits = self.map.minitiles.get((minitile_pixel.x, minitile_pixel.y), (False, 0))\r\n                # print(f"VISITAS {visits}")\r\n                if visits != 0:\r\n                    cost += visits * adicional_cost   # Additional penalty for previously visited swamp pixels\r\n                    # print(f"MINITILE YA VISITADO COSTO: {cost}")\r\n                    # print(f"VISITS: {visits}")\r\n            # else:\r\n            #     consecutive_swamps = 0\r\n        return cost\r\n    \r\n    def is_boring(self, minitile_tuple):\r\n        """Checks if a minitile is boring, meaning it has one or no walls around it."""\r\n        # TODO(Richo): Is this okay???\r\n        return self.count_walls_around(minitile_tuple) <= 1\r\n\r\n    def find_path(self, position, use_cache=True):\r\n        """Finds a path from the robot\'s position (terms of minitle) to a minitile not visited yet."""\r\n        self.start = position\r\n\r\n        """Performs a Dijkstra on the map\'s minitiles starting from the robot\'s position and finishing\r\n        in a minitile not visited yet. If no minitile is found, it returns the path to the start.\r\n        A very good explanation of the algorithm can be found here:\r\n        https://www.redblobgames.com/pathfinding/a-star/introduction.html#breadth-first-search"""\r\n        robot_pos = self.map.world_to_minitile(position)\r\n        start = (robot_pos.x, robot_pos.y)\r\n        \r\n        # The order in which we check the neighbour minitiles is important, we want to prioritize\r\n        # horizontal and vertical movements vs diagonals, so we put them first in the list\r\n        cardinals = [(-1, 0), (0, -1), ( 1, 0), (0,  1)]\r\n        diagonals = [(-1, -1), (1, -1), ( 1,  1), (-1, 1)]\r\n        directions = cardinals + diagonals\r\n\r\n        frontier = [] # Priority queue of points to explore\r\n        # Now, each each tuple has these elements: [priority_score, counter, minitile_tuple]\r\n        heappush(frontier, [0.0, 0, start]) # Counter used to break ties in the priority queue\r\n        came_from = {} # path A->B is stored as came_from[B] == A\r\n        came_from[start] = None\r\n        cost_so_far = {start: 0}\r\n        # consecutive_swamps = {start:0}\r\n        self.penalty_scores = {}\r\n        self.priority_scores = {}\r\n        pixel_paths = {}\r\n        pixel_pos = {start: self.map.world_to_pixel(position)}\r\n\r\n        candidates = []\r\n        counter = 0\r\n        while len(frontier) > 0:\r\n            _, _, current = heappop(frontier)\r\n\r\n            # If we find 15 candidates (not visited), we stop searching\r\n            is_visited, _ = self.map.is_visited(current)\r\n            if current != start and not is_visited:\r\n                if not self.is_boring(current) and not current in candidates:\r\n                    candidates.append(current)\r\n                    if len(candidates) > 15:\r\n                        break\r\n            \r\n            # Verifying the neighbours of the current minitile.\r\n            for dx, dy in directions:\r\n                neighbor = (current[0] + dx, current[1] + dy)\r\n                if not self.map.is_valid(neighbor):\r\n                    continue\r\n                \r\n                pixel_path = None # We will try to find a cached pixel path first, if not found, we will calculate it.\r\n                if use_cache:\r\n                    pixel_path = self.find_cached_pixel_path(current, neighbor)\r\n                if pixel_path == None:\r\n                    current_px = pixel_pos.get(current)\r\n                    if current_px == None:\r\n                        current_px = self.map.world_to_pixel(self.map.minitile_to_world(Vector.from_tuple(current)))\r\n\r\n                    neighbor_px = pixel_pos.get(neighbor)\r\n                    if neighbor_px == None:\r\n                        neighbor_px = self.map.world_to_pixel(self.map.minitile_to_world(Vector.from_tuple(neighbor)))\r\n\r\n                    pixel_path = self.find_pixel_path(current_px, neighbor_px)\r\n                    pixel_path = self.smooth_path(pixel_path) # We smooth the path to avoid unnecessary zig-zagging.\r\n                    self.store_pixel_path(current, neighbor, pixel_path)\r\n                    self.store_pixel_path(neighbor, current, pixel_path[::-1]) # To avoid redundant calculations, we store the reverse path as well.\r\n\r\n                if len(pixel_path) == 0:\r\n                    continue \r\n                \r\n                def get_penalty_score(wall_count):\r\n                    return 0 # -25.0/7 * wall_count + 20 \r\n                \r\n                # The neighbour cost is the acumulated cost of the current minitile plus the cost calculated from the current minitile to the neighbour\r\n                neighbor_cost = cost_so_far[current] + self.calculate_cost_pixel_path(pixel_path)\r\n                walls_around = self.count_walls_around(neighbor)\r\n                penalty_score = get_penalty_score(walls_around)\r\n\r\n                # We combine interest and cost into a single score\r\n                priority_score = neighbor_cost + penalty_score\r\n\r\n                #If the robot finds a cheaper path than the previous one, we take that path\r\n                if neighbor not in cost_so_far or neighbor_cost < cost_so_far[neighbor]:\r\n                    # consecutive_swamps[neighbor] = new_consecutive\r\n                    pixel_paths[(current, neighbor)] = pixel_path\r\n                    pixel_pos[neighbor] = pixel_path[-1]\r\n                    cost_so_far[neighbor] = neighbor_cost\r\n                    self.penalty_scores[neighbor] = penalty_score\r\n                    self.priority_scores[neighbor] = priority_score\r\n                    self.walls_around[neighbor] = walls_around\r\n                    came_from[neighbor] = current\r\n                    counter += 1\r\n\r\n                    # Push the neighbour into the priority queue with its priority score and a counter to break ties\r\n                    heappush(frontier, [priority_score, counter, neighbor])  \r\n\r\n        self.cost_so_far = cost_so_far\r\n        self.came_from = came_from\r\n        self.tsp = {}\r\n\r\n        # If we find a candidate target\r\n        if len(candidates) > 0:\r\n            clusters = self.paint_clusters(candidates)\r\n            dead_ends = self.find_dead_ends(clusters)\r\n            self.tsp = {\r\n                "candidates": candidates,\r\n                "clusters": [list(c) for c in clusters],\r\n                "dead_ends": list(dead_ends)\r\n            }\r\n\r\n            #We prioritize dead ends if the cost of the dead end is closer/cheaper than the closest_target + 6px of margin.\r\n            #The idea is to visit first dead ends because it will cost much more later.\r\n            closest_target = candidates[0]\r\n            dead_end_target = next((candidate for candidate in candidates if candidate in dead_ends), None)\r\n            if dead_end_target != None and cost_so_far[dead_end_target] < cost_so_far[closest_target] + MINITILE_SIZE_PX/2:\r\n                target = dead_end_target\r\n            else:\r\n                target = closest_target\r\n\r\n            path = self.reconstruct_path(came_from, pixel_paths, start, target)\r\n            self.path = path\r\n            return path\r\n        \r\n        # If we didn\'t find a minitile, we try go back to the start\r\n        # If (0,0) not in came_from, it means that the robot is stuck and cannot find a path to any minitile, including the start.\r\n        if (0,0) not in came_from: # This bug should never happen, but just in case\r\n            print(f"ACAACA!!!")\r\n            # utils.log_debug(f"ACAACA: came_from {came_from}, pixel_paths: {pixel_paths}")\r\n            if use_cache == True:\r\n                new_path = self.find_path(position, False)\r\n                self.path = new_path\r\n                return new_path\r\n            else:\r\n                self.path = []\r\n                return []\r\n        else:\r\n            path = self.reconstruct_path(came_from, pixel_paths, start, (0, 0))\r\n            self.path = path\r\n            return path\r\n\r\n    def count_walls_around(self, minitile):\r\n        x, y = minitile \r\n        wall_count = 0\r\n        # Counting how many walls are around the minitile, including diagonals\r\n        cardinals = [(-1, 0), (0, -1), ( 1, 0), (0,  1)]\r\n        diagonals = [(-1, -1), (1, -1), ( 1,  1), (-1, 1)]\r\n        directions = cardinals + diagonals\r\n        for dx, dy in directions:\r\n            neighbour = (x + dx, y + dy)\r\n            if self.map.has_walls(neighbour):\r\n                wall_count += 1\r\n        return wall_count\r\n\r\n    def reconstruct_path(self, came_from, pixel_paths, start, target):\r\n        """Turns the came_from table into a LIST of points from start to target.\r\n        came_from should contain the path from start to any valid minitile (including target)"""\r\n        current = target\r\n        path = []\r\n        \r\n        while current != start:\r\n            prev = came_from[current]\r\n            pixel_path = pixel_paths[(prev, current)]\r\n            \r\n            for p in pixel_path[::-1]:\r\n                path.append(self.map.pixel_to_world(p))\r\n\r\n            current = prev\r\n\r\n        path.reverse()\r\n        return self.smooth_path(path)\r\n    \r\n\r\n    def are_colinear(self, a, b, c, margin=1e-9):\r\n        """Checks if vectors are aligned."""\r\n        v1x, v1y=b.x-a.x,b.y-a.y\r\n        v2x, v2y=c.x-b.x,c.y-b.y\r\n        dot = v1x*v2x+v1y*v2y\r\n        mag1_sq = v1x**2 + v1y**2\r\n        mag2_sq = v2x**2 + v2y**2\r\n        return abs(dot**2 - mag1_sq * mag2_sq) < margin\r\n\r\n    def smooth_path(self, path):\r\n        """Simplifies the path lenght by removing colinear points."""\r\n        filtered = []\r\n        for p in path:\r\n            while (len(filtered) >= 2) and (self.are_colinear(filtered[-2], filtered[-1], p)) and (filtered[-1].distance_to(filtered[-2]) < (MINITILE_SIZE_PX / 2)):\r\n                filtered.pop()\r\n            filtered.append(p)\r\n        return filtered\r\n\r\n    def paint_clusters(self, minitiles):\r\n        """Agrupates a minitile cluster."""\r\n        groups = {m: -1 for m in minitiles}\r\n        idx = 0\r\n        for minitile in minitiles:\r\n            group = groups.get(minitile)\r\n            if group != -1: continue\r\n            \r\n            self.flood_fill(minitile, groups, idx)\r\n            idx += 1\r\n        \r\n        clusters = {}\r\n        for minitile, group_id in groups.items():\r\n            if group_id not in clusters:\r\n                clusters[group_id] = set([minitile])\r\n            else:\r\n                clusters[group_id].add(minitile)\r\n        return list(clusters.values())\r\n    \r\n    def flood_fill(self, minitile, groups, group_id):\r\n        """Flood fill algorithm to group minitiles into clusters."""\r\n        frontier = deque()\r\n        frontier.append(minitile)\r\n        came_from = {}\r\n        came_from[minitile] = None\r\n        cost_so_far = {minitile: 0}\r\n        \r\n        directions = [(-1, 0), (0, -1), ( 1, 0), (0,  1)] # Only using cardinal directions for do not selecting extra minitiles to clusters\r\n\r\n        while len(frontier) > 0:\r\n            current = frontier.popleft()\r\n\r\n            if groups.get(current) == -1:\r\n                groups[current] = group_id\r\n\r\n            for dx, dy in directions:\r\n                neighbor = (current[0] + dx, current[1] + dy)\r\n                if not self.map.is_valid(neighbor):\r\n                    continue\r\n                is_visited, _ = self.map.is_visited(neighbor)\r\n                if is_visited:\r\n                    continue\r\n                if groups.get(neighbor) != -1:\r\n                    continue\r\n                \r\n                pixel_path = self.find_cached_pixel_path(current, neighbor)\r\n                if pixel_path == None or len(pixel_path) == 0:\r\n                    continue\r\n\r\n                neighbor_cost = cost_so_far[current] + 1\r\n                if neighbor not in cost_so_far:\r\n                    cost_so_far[neighbor] = neighbor_cost\r\n                    came_from[neighbor] = current\r\n                    frontier.append(neighbor)\r\n        \r\n    def find_dead_ends(self, clusters):\r\n        """Finds dead ends in the clusters of minitiles."""\r\n        dead_ends = set()\r\n        for cluster in clusters:\r\n            if self.is_dead_end(cluster):\r\n                for minitile in cluster:\r\n                    dead_ends.add(minitile)\r\n        return dead_ends\r\n\r\n    def is_dead_end(self, cluster):\r\n        """Checks if a cluster of minitiles is a dead end."""\r\n        if len(cluster) > 3: \r\n            return False\r\n        \r\n        directions = [(-1, 0), (0, -1), ( 1, 0), (0,  1)]\r\n        for minitile in cluster:\r\n            neighbour_paths = self.pixel_paths.get(minitile) \r\n            for dx, dy in directions:\r\n                """Discarding clusters where their minitiles are potential \'open map regions\'"""\r\n                neighbour = (minitile[0] + dx, minitile[1] + dy)\r\n                if neighbour not in neighbour_paths: continue\r\n                is_visited, _ = self.map.is_visited(neighbour)\r\n                if is_visited: continue\r\n                if self.map.has_walls(neighbour): continue\r\n                if neighbour in cluster: continue\r\n                if self.is_boring(neighbour): continue\r\n                # If theres no minitile that follows the condition, the whole cluster is not a dead end\r\n                return False\r\n        return True\r\n\r\n    def find_pixel_path(self, start, target):\r\n        """As we are using greedy algorythm, we are now using a priority queue to explore the points.\r\n        The first element is the distance to the target, the second is a counter to break ties in the priority queue.\r\n        Ref: https://www.redblobgames.com/pathfinding/a-star/introduction.html#breadth-first-search"""\r\n\r\n        start_mintile = self.map.world_to_minitile(self.map.pixel_to_world(start))\r\n        target_minitle = self.map.world_to_minitile(self.map.pixel_to_world(target))\r\n        if start_mintile == target_minitle:\r\n            return []\r\n        \r\n        if not self.map.is_pixel_traversable(start):\r\n            print(f"Start {start} is not traversable!")\r\n\r\n        frontier = [] # Priority queue of points to explore\r\n        heappush(frontier, [0.0, 0, start]) # Counter used to break ties in the priority queue\r\n        came_from = {}\r\n        came_from[start] = None\r\n        cost_so_far = {start: 0}\r\n\r\n        closest = start\r\n        closest_dist = math.inf\r\n\r\n        counter = 0\r\n        path = None\r\n        while len(frontier) > 0:\r\n            _, _, current = heappop(frontier)\r\n\r\n            if current == target:\r\n                path = self.reconstruct_pixel_path(came_from, start, current)\r\n                break\r\n            \r\n            # TODO(Richo): Early exit if there is no path after some distance!\r\n            if cost_so_far[current] > MINITILE_SIZE_PX*1.42: # 1.42 is the diagonal of a minitile (sqrt(2))\r\n                break\r\n            \r\n            # Looking for the closest neighbour.\r\n            for neighbour in self.map.get_traversable_pixel_neighbours(current):\r\n                if neighbour not in came_from:\r\n                    dist_to_target = target.distance_to(neighbour)\r\n                    counter += 1\r\n                    heappush(frontier, [dist_to_target, counter, neighbour])\r\n                    came_from[neighbour] = current\r\n                    cost_so_far[neighbour] = cost_so_far[current] + 1\r\n\r\n                    if dist_to_target < closest_dist:\r\n                        closest = neighbour\r\n                        closest_dist = dist_to_target\r\n\r\n        if path is not None:\r\n            # print(f"Found valid path! {path}")\r\n            return path\r\n        \r\n        closest_minitile = self.map.world_to_minitile(self.map.pixel_to_world(closest))\r\n        if closest_minitile != target_minitle:\r\n            return []\r\n        \r\n        # Minimum bounding box of the target minitile, to check if the closest pixel is inside it. (1/8 of a tile is the margin)\r\n        left = target.x - MINITILE_SIZE_PX//2\r\n        right = target.x + MINITILE_SIZE_PX//2\r\n        top = target.y - MINITILE_SIZE_PX//2\r\n        bottom = target.y + MINITILE_SIZE_PX//2\r\n        if closest.x > left and closest.x < right and closest.y > top and closest.y < bottom:\r\n            path = self.reconstruct_pixel_path(came_from, start, closest)\r\n            return path\r\n        else:\r\n            # print(f"NO path found!")\r\n            return []       \r\n        \r\n    def reconstruct_pixel_path(self, came_from, start, target):\r\n        """Turns the came_from table into a LIST of points from start to target.\r\n        came_from should contain the path from start to any valid minitile (including target)"""\r\n        current = target\r\n        path = [target]\r\n        \r\n        while current != start:\r\n            current = came_from[current]\r\n            path.append(current)\r\n        \r\n        path.append(start) # Make sure start is also in the path\r\n        path.reverse()\r\n        return path\r\n')
    __stickytape_write_module('navigation/map.py', b'import numpy as np\r\nfrom vector import Vector\r\nimport cv2\r\nfrom vector import Vector\r\n\r\nfrom tile_classifier import TileType\r\n\r\nTILE_SIZE = 0.12\r\nMINITILE_SIZE = TILE_SIZE/2\r\nSCALE = 200\r\nMINITILE_SIZE_PX = int(SCALE * MINITILE_SIZE)\r\nLOP_INCREMENT = 2\r\n\r\nclass Map:\r\n    def __init__(self):\r\n        initial_size = 12\r\n        self.img = np.ones((initial_size, initial_size), dtype=np.uint8) * 255\r\n        self.visited_img = np.ones((initial_size, initial_size), dtype=np.uint8) * 255\r\n        self.origin = Vector.ONE*(initial_size // 2)\r\n        self.minitiles = {}\r\n        self.walls = {}\r\n        self.lop_pixels = {}\r\n        self.active_region = {\r\n            "top_left": Vector(self.origin.x, self.origin.y),\r\n            "bottom_right": Vector(self.origin.x, self.origin.y)\r\n        }\r\n\r\n    def get_scale(self):\r\n        return SCALE\r\n    \r\n    def get_image(self):\r\n        return self.img\r\n    \r\n    def get_visited_image(self):\r\n        return self.visited_img\r\n\r\n    def world_to_pixel(self, point):\r\n        """Transforms point from world coordinates to pixel coordinates."""\r\n        return (point * SCALE).round()\r\n\r\n    def pixel_to_world(self, point):\r\n        """Transforms point from pixel coordinates to world coordinates."""\r\n        return (point) / SCALE\r\n    \r\n    def minitile_to_world(self, point):\r\n        """Transforms point from minitiles coordinates to world coordinates."""\r\n        # print(f"Converting minitile to world: {point}")\r\n        return point * MINITILE_SIZE\r\n    \r\n    def world_to_minitile(self, point):\r\n        """Transforms point from world coordinates to minitile coordinates."""\r\n        return (point/MINITILE_SIZE).round()\r\n    \r\n    def get_pixel_neighbours(self, pixel):\r\n        """Returns the 8 neighbours of a pixel (cardinal and diagonals)."""\r\n        directions = [\r\n            Vector(-1, -1), Vector(-1, 0), Vector(-1, 1),  \r\n            Vector(0, -1),                 Vector(0, 1),    \r\n            Vector(1, -1), Vector(1, 0), Vector(1, 1)      \r\n        ]\r\n        result = []\r\n        for dir in directions:\r\n            p = pixel + dir\r\n            result.append(p)\r\n        return result\r\n    \r\n    def get_traversable_pixel_neighbours(self, pixel):\r\n        """Iterates trough the pixel neighbours and returns only the traversable ones."""\r\n        result = []\r\n        for p in self.get_pixel_neighbours(pixel):\r\n            if self.is_pixel_traversable(p):\r\n                result.append(p)\r\n        return result\r\n\r\n    def is_visited(self, minitile_tuple):\r\n        """Checks if a minitile has been visited."""\r\n        is_on_dict, visits =  self.minitiles.get(minitile_tuple, (False, 0))\r\n        return is_on_dict, visits\r\n    \r\n    def get_all_unvisited(self):\r\n        """Returns a list of all unvisited minitiles."""\r\n        return [pos for pos, (visited, _) in self.minitiles.items() if not visited]\r\n    \r\n    def is_valid(self, minitile_tuple):\r\n        """Checks if a minitile is valid (exists in the map)."""\r\n        return minitile_tuple in self.minitiles\r\n        \r\n    def is_traversable(self, point):\r\n        """Given a point, it returns if the point\'s pixel is traversable."""\r\n        pixel = self.world_to_pixel(point)\r\n        return self.is_pixel_traversable(pixel)\r\n    \r\n    def is_pixel_traversable(self, pixel, special_case=False):\r\n        """Checks if a pixel is traversable (relative to origin) based on the maps\'s images."""\r\n        pixel += self.origin\r\n        w, h = self.img.shape[0], self.img.shape[1]\r\n        if pixel.y >= h or pixel.x >= w: return False\r\n        if pixel.y < 0 or pixel.x < 0: return False\r\n        return self.img[pixel.y, pixel.x] != 0 or self.visited_img[pixel.y, pixel.x] == 0\r\n    \r\n    def is_pixel_swamp(self, pixel):\r\n        """Checks if a pixel is swamp (relative to origin) based on the map\'s image."""\r\n        pixel += self.origin\r\n        w, h = self.img.shape[0], self.img.shape[1]\r\n        if pixel.y >= h or pixel.x >= w: return False\r\n        if pixel.y < 0 or pixel.x < 0: return False\r\n        return self.img[pixel.y, pixel.x] == 128\r\n    \r\n    def has_walls(self, minitile):\r\n        """Checks if a minitile has walls."""\r\n        return self.walls.get(minitile, False)        \r\n        \r\n    def find_closest_traversable_point(self, target, robot_pos, special_case=False):\r\n        """Finds the closest traversable point of a target world pos."""\r\n        robot_pixel = self.world_to_pixel(robot_pos)\r\n        # print("Robot pixel:", robot_pixel)\r\n        if not self.is_pixel_traversable(robot_pixel, special_case):\r\n            return None\r\n        \r\n        target_pixel = self.world_to_pixel(target)\r\n        while not self.is_pixel_traversable(target_pixel):\r\n            neighbour_pixels = self.get_pixel_neighbours(target_pixel)\r\n            target_pixel = min(neighbour_pixels, key=lambda p: p.distance_to(robot_pixel))\r\n                \r\n        return self.pixel_to_world(target_pixel)\r\n            \r\n    def mark_lop(self, position):\r\n        """Marks a point as obstructed and expans lop if necessary."""\r\n        self.mark_as_obstructed(position)\r\n        lop_pixel = self.expand_lop_if_near(position)\r\n        self.lop_pixels[lop_pixel] = 1\r\n\r\n    def expand_lop_if_near(self, position):\r\n        """From a position given, expands the lop if its pixel position is near an existing lop pixel."""\r\n        lop_pixel = self.world_to_pixel(position) + self.origin\r\n        if len(self.lop_pixels) >= 1:\r\n            for pixel in self.lop_pixels:\r\n                distance = pixel.distance_to(lop_pixel)\r\n                if distance <= 15:\r\n                    self.lop_pixels[pixel] += LOP_INCREMENT\r\n                    self.mark_as_obstructed(pixel, self.lop_pixels[pixel], is_pixel = True) # "Key" is a pixel\r\n        return lop_pixel\r\n        \r\n    def mark_as_obstructed(self, position, radius=1, is_pixel=False):\r\n        """Sets the pixel at point as not traversable."""\r\n        if not is_pixel:\r\n            pixel = self.world_to_pixel(position) + self.origin\r\n        else:\r\n            pixel = position\r\n        cv2.circle(self.img, (pixel.x, pixel.y), radius, 0, cv2.FILLED)\r\n        cv2.circle(self.visited_img, (pixel.x, pixel.y), radius, 255, cv2.FILLED)\r\n\r\n    def mark_position_as_visited(self, point):\r\n        """Marks a point as visited in terms of pixel and minitile."""\r\n        # print(f"Marking position as visited: {point}")\r\n        minitile = self.world_to_minitile(point)\r\n        if self.minitiles.get((minitile.x, minitile.y), (False, 0))[0] == False:\r\n            self.minitiles[(minitile.x, minitile.y)] = (True, 0) # Changed structure: (minitile.x, minitile.y) -> visits\r\n        \r\n        robot_px = self.world_to_pixel(point) + self.origin\r\n        self.visited_img[int(robot_px.y), int(robot_px.x)] = 0\r\n    \r\n    def needs_expansion(self, lidar_points, robot_position):\r\n        """Checks if the map needs expansion based on the lidar_points or if robot is near the edge."""\r\n\r\n        # 1. Check LiDAR points first\r\n        for v in lidar_points:\r\n            point = self.world_to_pixel(v + robot_position) + self.origin\r\n            if not (0 <= point.x < self.img.shape[1] and 0 <= point.y < self.img.shape[0]):\r\n                return True\r\n\r\n        # 2. Now check if the robot is less than 50px from the edge\r\n        robot_position_pixels = self.world_to_pixel(robot_position) + self.origin\r\n        margin = 50\r\n        if (robot_position_pixels.x < margin or\r\n            robot_position_pixels.x >= self.img.shape[1] - margin or\r\n            robot_position_pixels.y < margin or\r\n            robot_position_pixels.y >= self.img.shape[0] - margin):\r\n            return True\r\n\r\n        return False\r\n\r\n    def expand_map(self):\r\n        """Expands the map if necessary."""\r\n        new_width = self.img.shape[1] * 2\r\n        new_height = self.img.shape[0] * 2\r\n        new_img = np.ones((new_height, new_width), dtype=np.uint8) * 255\r\n        new_visited = np.ones((new_height, new_width), dtype=np.uint8) * 255\r\n        new_overlay = np.ones((new_height, new_width, 3), dtype=np.uint8) * 255\r\n        \r\n        new_img[new_height // 4:new_height // 4 + self.img.shape[0], new_width // 4:new_width // 4 + self.img.shape[1]] = self.img\r\n        new_visited[new_height // 4:new_height // 4 + self.visited_img.shape[0], new_width // 4:new_width // 4 + self.visited_img.shape[1]] = self.visited_img\r\n        \r\n        self.img = new_img\r\n        self.visited_img = new_visited\r\n        self.origin = Vector.ONE*(new_width // 2)\r\n\r\n    def update_walls(self, lidar_points, robot_position):\r\n        """Plots lidar_points on the map texture and actualizes the map\'s active region."""\r\n        radius = None\r\n        for v in lidar_points:\r\n            point = self.world_to_pixel(v + robot_position) + self.origin\r\n            ray_dist = v.length() / TILE_SIZE\r\n            if ray_dist > 4: continue\r\n            # y= (-0.03/7) * x + 0.034\r\n            """Calculated a linear function in which we determine the radius of the wall according to the ray dist (from one to 4 tiles), if the distance is\r\n            less than one tile, the radius will be 0.03, and if its bigger than eight tiles, the radius is 0. Reduce the radius of the wall the further it is, \r\n            in order to reduce the probability of marking a pixel as not traversable when it is actually traversable, due to the inaccuracy of the gps"""\r\n            radius = (-0.03/7) * ray_dist + 0.029\r\n            if radius < 0:\r\n                radius = 0\r\n            elif radius > 0.03:\r\n                radius = 0.03\r\n            if 0 <= point.x < self.img.shape[1] and 0 <= point.y < self.img.shape[0]:\r\n                cv2.circle(self.img, (point.x, point.y), int(radius*SCALE)+1, 0, cv2.FILLED)\r\n\r\n            self.active_region = self.get_active_pixel_region(point, self.active_region)\r\n            \r\n            minitile = self.world_to_minitile(v + robot_position)\r\n            self.walls[(minitile.x, minitile.y)] = True\r\n\r\n    def get_active_pixel_region(self, pixel, active_region):\r\n        """Updates the active pixel region based on a given lidar point."""\r\n        pixel -= self.origin # Adjust pixel to the origin of the map (centre)\r\n\r\n        if pixel.x < active_region["top_left"].x:\r\n            active_region["top_left"].x = pixel.x\r\n        if pixel.y < self.active_region["top_left"].y:\r\n            active_region["top_left"].y = pixel.y\r\n\r\n        if pixel.x > self.active_region["bottom_right"].x:\r\n            active_region["bottom_right"].x = pixel.x\r\n        if pixel.y > self.active_region["bottom_right"].y:\r\n            active_region["bottom_right"].y = pixel.y\r\n        return active_region\r\n            \r\n    def update_black_holes(self, surrounding_tiles):\r\n        """Updates the map with black holes based on surrounding tiles types."""\r\n        for tile, type in surrounding_tiles.items():\r\n            if type == TileType.BLACK_HOLE:\r\n                position = Vector(tile[0] * TILE_SIZE, tile[1] * TILE_SIZE)\r\n                top_left = self.world_to_pixel(position - Vector.ONE*0.09) + self.origin\r\n                bottom_right = self.world_to_pixel(position + Vector.ONE*0.09) + self.origin\r\n                cv2.rectangle(self.img, (top_left.x, top_left.y), (bottom_right.x, bottom_right.y), 0, cv2.FILLED)\r\n\r\n    def update_swamps(self, surrounding_tiles):\r\n        """Updates the map with swamps based on surrounding tiles types."""\r\n        for tile, type in surrounding_tiles.items():\r\n            if type == TileType.SWAMP:\r\n                position = Vector(tile[0] * TILE_SIZE, tile[1] * TILE_SIZE)\r\n                top_left = self.world_to_pixel(position - Vector.ONE*0.06) + self.origin\r\n                bottom_right = self.world_to_pixel(position + Vector.ONE*0.06) + self.origin\r\n                # Swamps are represented differently in order to distinguish them from other tiles and try not to visit them\r\n                cv2.rectangle(self.img, (top_left.x, top_left.y), (bottom_right.x, bottom_right.y), 128, cv2.FILLED)\r\n    \r\n    def update_visited(self, robot_position):\r\n        """Marks the robot\'s minitile as visited."""\r\n        robot_minitile = self.world_to_minitile(robot_position)\r\n        \r\n        robot_pixel = self.world_to_pixel(robot_position) \r\n        bool, visits = self.minitiles.get((robot_minitile.x, robot_minitile.y), (False, 0))\r\n        if bool:\r\n            self.minitiles[(robot_minitile.x, robot_minitile.y)] = (bool, visits)\r\n        # print(f"Minitiles dict in update_visited: {self.minitiles}")\r\n\r\n        robot_px = self.world_to_pixel(robot_position) + self.origin\r\n        self.visited_img[int(robot_px.y), int(robot_px.x)] = 0\r\n\r\n    def increase_visit_count(self, minitile_tuple,increment=1):\r\n        """Increases the visit count of a minitile."""\r\n        if minitile_tuple in self.minitiles:\r\n            visited, visits = self.minitiles[minitile_tuple]\r\n            self.minitiles[minitile_tuple] = (visited, visits + increment) \r\n\r\n    def update_minitiles(self, robot_position):\r\n        """Marks adjacent minitiles as valid."""\r\n        robot_minitile = self.world_to_minitile(robot_position)\r\n        directions = []\r\n        for dx in range(-4, 5):\r\n            for dy in range(-4, 5):\r\n                if dx == 0 and dy == 0: continue\r\n                v = Vector(dx, dy)\r\n                directions.append(v)\r\n\r\n        for delta in directions:\r\n            minitile = robot_minitile + delta\r\n            minitile_pos = self.minitile_to_world(minitile)\r\n            minitile_pixel = self.world_to_pixel(minitile_pos) + self.origin\r\n            x1 = int(minitile_pixel.x - MINITILE_SIZE_PX/2)\r\n            y1 = int(minitile_pixel.y - MINITILE_SIZE_PX/2)\r\n            x2 = x1 + MINITILE_SIZE_PX\r\n            y2 = y1 + MINITILE_SIZE_PX\r\n\r\n            if (x1 < 0 or y1 < 0 or x2 > self.img.shape[1] or y2 > self.img.shape[0]):\r\n                continue\r\n\r\n            minitile_tuple = (minitile.x, minitile.y)\r\n            is_visited, visits = self.is_visited(minitile_tuple)\r\n\r\n            if minitile_tuple not in self.minitiles or is_visited:\r\n                self.minitiles[minitile_tuple] = (is_visited, visits)\r\n    \r\n    def update(self, robot_position, lidar_points, surrounding_tiles):\r\n        while self.needs_expansion(lidar_points, robot_position):\r\n            self.expand_map()\r\n        \r\n        self.update_walls(lidar_points, robot_position)\r\n        self.update_black_holes(surrounding_tiles)\r\n        self.update_swamps(surrounding_tiles)\r\n        self.update_visited(robot_position)\r\n        self.update_minitiles(robot_position)\r\n        \r\n        # # self.display_map(robot_position) # DEBUG\r\n')
    __stickytape_write_module('tile_classifier.py', b'from enum import Enum\r\nfrom vector import Vector\r\nfrom side import Side\r\nimport utils\r\nimport math\r\nimport cv2\r\n\r\nDEBUGGING_3_CAMS = True\r\n\r\nclass TileType(Enum):\r\n    BLACK_HOLE = \'2\'\r\n    SWAMP = \'3\'\r\n    CHECKPOINT = \'4\'\r\n    STARTING = \'5\'\r\n    BLUE = \'b\'\r\n    YELLOW = \'y\'\r\n    GREEN = \'g\'\r\n    PURPLE = \'p\'\r\n    ORANGE = \'o\'\r\n    RED = \'r\'\r\n    STANDARD = \'s\'\r\n    UNKNOWN = \'u\'\r\n    OBSTACLE = \'x\'\r\n\r\nclass TileClassifier:\r\n    def __init__(self):\r\n        self.counter = 0\r\n    \r\n    def get_surrounding_tiles(self, robot):\r\n        """Returns a dictionary of surrounding tiles and their corresponding types based on the robot\'s camera images."""\r\n        result = {}\r\n\r\n        self.analyze_pixels(self.get_tile_pointed_by_front_camera(robot), robot.get_camera_from_side(Side.FRONT), result)\r\n        self.analyze_pixels(self.get_tile_pointed_by_left_camera(robot), robot.get_camera_from_side(Side.LEFT), result)\r\n        if DEBUGGING_3_CAMS:\r\n            self.analyze_pixels(self.get_tile_pointed_by_right_camera(robot), robot.get_camera_from_side(Side.RIGHT), result)\r\n        \r\n        # print(f"Surrounding tiles: {result}")\r\n        # print("-"*60)\r\n\r\n        return result\r\n\r\n    def position_to_grid(self, pos):\r\n        """Converts a world position to a grid position (relative to robot\'s origin tile)."""\r\n        col = round(pos.x / 0.12)\r\n        row = round(pos.y / 0.12)\r\n        return (col, row)\r\n    \r\n    def get_tile_pointed_by_front_camera(self, robot): # TODO (Martu): Optimize!!\r\n        """Returns the tile(s) pointed by the front camera based on the robot\'s position, direction, and lidar image."""\r\n        tiles = []\r\n        robot_pos = robot.get_position()\r\n        robot_direction = robot.get_forward_vector()\r\n        robot_lidar_image = robot.get_lidar_image()\r\n        # if(robot_lidar_image[256] > 0.099 and robot_lidar_image[213] > 0.099 and robot_lidar_image[299] > 0.099):\r\n        if min(robot_lidar_image[220:292]) > 0.099:\r\n            robot_on_horizontal_border = utils.point_on_horizontal_border(robot_pos)\r\n            robot_on_vertical_border = utils.point_on_vertical_border(robot_pos)\r\n            if robot_on_horizontal_border:\r\n                # If my rotation is close to 90 or 270 degrees\r\n                if abs(robot_direction.dot(Vector.RIGHT)) > 0.99:\r\n                    front_camera_pointer = robot_pos + robot_direction * 0.084\r\n                    on_vertical_border = utils.point_on_vertical_border(front_camera_pointer)\r\n                    if not on_vertical_border:\r\n                        front_camera_pointer = robot_pos + robot_direction.rotated(0.34) * 0.089 # Primero la tile a la izquierda\r\n                        tile = self.position_to_grid(front_camera_pointer)\r\n                        tiles.append(tile)\r\n                        front_camera_pointer = robot_pos + robot_direction.rotated(-0.34) * 0.089 # Luego la tile a la derecha\r\n                        tile = self.position_to_grid(front_camera_pointer)\r\n                        tiles.append(tile)\r\n                        return tiles\r\n                return None\r\n            elif robot_on_vertical_border:\r\n                # If my rotation is close to 0 or 180 degrees\r\n                if abs(robot_direction.dot(Vector.UP)) > 0.99:\r\n                    front_camera_pointer = front_camera_pointer = robot_pos + robot_direction * 0.084\r\n                    on_horizontal_border = utils.point_on_horizontal_border(front_camera_pointer)\r\n                    if not on_horizontal_border:\r\n                        front_camera_pointer = robot_pos + robot_direction.rotated(0.34) * 0.089\r\n                        tile = self.position_to_grid(front_camera_pointer)\r\n                        tiles.append(tile)\r\n                        front_camera_pointer = robot_pos + robot_direction.rotated(-0.34) * 0.089\r\n                        tile = self.position_to_grid(front_camera_pointer)\r\n                        tiles.append(tile)\r\n                        return tiles\r\n                return None\r\n            elif not robot_on_horizontal_border and not robot_on_vertical_border:\r\n                front_camera_pointer = front_camera_pointer = robot_pos + robot_direction * 0.084\r\n                on_horizontal_border = utils.point_on_horizontal_border(front_camera_pointer)\r\n                on_vertical_border = utils.point_on_vertical_border(front_camera_pointer)\r\n                if on_horizontal_border or on_vertical_border:\r\n                    return None\r\n                tile = self.position_to_grid(front_camera_pointer)\r\n                tiles.append(tile)\r\n                return tiles\r\n        else:\r\n            return None\r\n        \r\n    def get_tile_pointed_by_left_camera(self, robot):\r\n        """Returns the tile pointed by the left camera based on the robot\'s position, direction, and lidar image."""\r\n        tiles = []\r\n        robot_pos = robot.get_position()\r\n        robot_direction = robot.get_forward_vector()\r\n        robot_lidar_image = robot.get_lidar_image()\r\n        if min(robot_lidar_image[92:164]) > 0.099:\r\n            point_cs = robot_pos + robot_direction.rotated(math.pi/2) * 0.084\r\n\r\n            on_border_x = utils.point_on_vertical_border(point_cs)\r\n            on_border_y = utils.point_on_horizontal_border(point_cs)\r\n\r\n            if on_border_x or on_border_y:\r\n                # print("No te clasifico, tile")\r\n                return None\r\n            \r\n            tile = self.position_to_grid(point_cs)\r\n            tiles.append(tile)\r\n            return tiles\r\n        else:\r\n            return None\r\n        \r\n    def get_tile_pointed_by_right_camera(self, robot):\r\n        """Returns the tile pointed by the right camera based on the robot\'s position, direction, and lidar image."""\r\n        tiles = []\r\n        robot_pos = robot.get_position()\r\n        robot_direction = robot.get_forward_vector()\r\n        robot_lidar_image = robot.get_lidar_image()\r\n        if min(robot_lidar_image[348:420]) > 0.099:\r\n            point_cs = robot_pos + robot_direction.rotated(-math.pi/2) * 0.084\r\n\r\n            on_border_x = utils.point_on_vertical_border(point_cs)\r\n            on_border_y = utils.point_on_horizontal_border(point_cs)\r\n\r\n            if on_border_x or on_border_y:\r\n                # print("No te clasifico, tile")\r\n                return None\r\n            \r\n            tile = self.position_to_grid(point_cs)\r\n            tiles.append(tile)\r\n            return tiles\r\n        else:\r\n            return None\r\n    \r\n    def analyze_pixels(self, tiles, img, result):\r\n        """Analyzes the pixels of the given tiles in the image and updates the result dictionary with their types."""\r\n        special_case = False\r\n        if tiles is None: return None\r\n        # if (3,1) in tiles or (1, 5) in tiles or (1, 0) in tiles: special_case = True\r\n        if len(tiles) == 1:\r\n            b, g, r, _ = img[39, 20] # Front tile\r\n            m = Floor(r, g, b).get_tile_type(tiles, special_case)\r\n            b, g, r, _ = img[35, 20]\r\n            w = Floor(r, g, b).get_tile_type(tiles, special_case)\r\n            if m == w and m is not None:\r\n                result[tiles[0]] = m\r\n        else:\r\n            b, g, r, _ = img[39, 0] # Left tile\r\n            m = Floor(r, g, b).get_tile_type(tiles[0], special_case)\r\n            b, g, r, _ = img[35, 0]\r\n            w = Floor(r, g, b).get_tile_type(tiles[0], special_case)\r\n            if m == w and m is not None:\r\n                result[tiles[0]] = m\r\n\r\n            b, g, r, _ = img[39, 39] # Right tile\r\n            m = Floor(r, g, b).get_tile_type(tiles[1], special_case)\r\n            b, g, r, _ = img[35, 39]\r\n            w = Floor(r, g, b).get_tile_type(tiles[1],  special_case)\r\n            if m == w and m is not None:\r\n                result[tiles[1]] = m\r\n\r\n\r\nclass Floor:\r\n    def __init__(self, r, g, b):\r\n        # NOTE(Richo): These RGB values come from a numpy array, so we need to cast them \r\n        # as integer, otherwise we risk an overflow when doing arithmetic with them.\r\n        self.red = int(r)\r\n        self.green = int(g)\r\n        self.blue = int(b)\r\n\r\n    def get_tile_type(self, tile = None, special_case = False):\r\n        """Determines the type of the tile based on its RGB values and returns the corresponding TileType."""\r\n        if special_case: pass\r\n        if self.is_black_hole():\r\n            return TileType.BLACK_HOLE\r\n        elif self.is_swamp():\r\n            return TileType.SWAMP\r\n        elif self.is_blue():\r\n            return TileType.BLUE\r\n        elif self.is_green():\r\n            return TileType.GREEN\r\n        elif self.is_purple():\r\n            return TileType.PURPLE\r\n        elif self.is_red():\r\n            return TileType.RED\r\n        elif self.is_orange():\r\n            return TileType.ORANGE\r\n        elif self.is_yellow():\r\n            return TileType.YELLOW\r\n        elif self.is_checkpoint():\r\n            return TileType.CHECKPOINT\r\n        elif self.is_standard():\r\n            return TileType.STANDARD\r\n\r\n    def is_swamp(self):\r\n        return abs(self.red - 169) < 15 \\\r\n            and abs(self.green - 135) < 15 \\\r\n            and abs(self.blue - 75) < 15\r\n    \r\n    def is_black_hole(self):\r\n        return abs(self.red) <= 30 \\\r\n            and abs(self.green) <= 30 \\\r\n            and abs(self.blue) <= 30 \\\r\n            and abs(self.red - self.green) < 2 \\\r\n            and abs(self.red - self.blue) < 2\r\n\r\n    def is_green(self):\r\n        return abs(self.red - 25) < 15 \\\r\n            and abs(self.green - 227) < 15 \\\r\n            and abs(self.blue - 25) < 15\r\n    \r\n    def is_yellow(self):\r\n        return abs(self.red - 234) < 15 \\\r\n            and abs(self.green - 234) < 15 \\\r\n            and abs(self.blue - 47) < 15\r\n    \r\n    def is_red(self):\r\n        return abs(self.red - 234) < 15 \\\r\n            and abs(self.green - 47) < 15 \\\r\n            and abs(self.blue - 47) < 15\r\n    \r\n    def is_blue(self):\r\n        return abs(self.red - 45) < 5 \\\r\n            and abs(self.green - 45) < 5 \\\r\n            and abs(self.blue - 230) < 5\r\n    \r\n    def is_purple(self):\r\n        return abs(self.red - 100) < 10 \\\r\n            and abs(self.green - 45) < 5 \\\r\n            and abs(self.blue - 180) < 10\r\n    \r\n    def is_standard(self):\r\n        return abs(self.red - 195) < 4 \\\r\n            and abs(self.green - 195) < 4 \\\r\n            and abs(self.blue - 195) < 4\r\n    \r\n    def is_checkpoint(self):\r\n        dif_green_blue = abs(self.blue-self.green)\r\n        dif_green_red = abs(self.red-self.green)\r\n        return dif_green_blue < 25 and dif_green_red <= 15 and self.blue > 35 \\\r\n        and self.red > 35 and self.green > 35 and self.red < 185 and self.green < 185 and self.blue < 185\r\n        \r\n    def is_orange(self):\r\n        return abs(self.red - 234) < 15 \\\r\n            and abs(self.green - 188) < 15 \\\r\n            and abs(self.blue - 47) < 15\r\n    \r\n# floor = Floor(42, 48, 66)\r\n# print(floor.is_checkpoint())')
    __stickytape_write_module('image.py', b'import cv2\r\nimport utils\r\nimport numpy as np\r\nfrom enum import Enum\r\nfrom vector import Vector\r\nfrom decimal import Decimal\r\nfrom fractions import Fraction\r\n\r\nMIN_AREA = 100\r\nMIN_COGNITIVE_AREA = 500\r\n\r\nclass ColourValues(Enum):\r\n    """This class defines the RGB values for the colours that cognitive targets contain inside them (each possible ring colour)."""\r\n    # In terms of RGB values\r\n    BLACK = (0, 0, 0)\r\n    RED = (207, 0, 0)\r\n    BLUE =  (0, 0, 207)\r\n    GREEN = (0, 207, 0)\r\n    YELLOW = (207, 207, 0)\r\n\r\nclass ColourScores(Enum):\r\n    """This class defines the scores for the colours that cognitive targets contain inside them (each possible ring colour)."""\r\n    BLACK = -2\r\n    RED = -1\r\n    YELLOW = 0\r\n    GREEN = 1\r\n    BLUE = 2\r\n\r\nclass ImageProcessor:\r\n\r\n    def __init__(self):\r\n        self.last_token_position = Vector(10000, 10000)\r\n        self.last_token_direction = Vector.ONE\r\n        self.counter = 0\r\n        self.debugging = False\r\n\r\n    def debug_show(self, img, filename = "img"):\r\n        """Displays the image for debugging purposes and saves it with the given filename."""\r\n        cv2.imwrite(f\'{filename}.png\', img)\r\n        cv2.imshow(filename, img)\r\n        cv2.waitKey(0)\r\n        cv2.destroyAllWindows()\r\n\r\n    def clean_image(self, converted_img, thresh_value = 125):\r\n        """It cleans the image in order to obtain de contour with children and without parent (hierarchy).\r\n        Read this Opencv documentation: https://docs.opencv.org/4.x/d9/d8b/tutorial_py_contours_hierarchy.html"""\r\n        if converted_img is None:\r\n            return None, None\r\n        aux_img = converted_img.copy()\r\n        grey = cv2.cvtColor(converted_img, cv2.COLOR_BGR2GRAY)\r\n        _, thresh = cv2.threshold(grey, thresh_value, 255, cv2.THRESH_BINARY)\r\n        contours, hierarchy = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n        if contours is None: return None, None\r\n        if len(contours) == 1:\r\n            """In case of only one contour, a color pixel count is done to discard already seen signs or false positives"""\r\n            contour = contours[0]\r\n            _, _, _, white_count, grey_count, _, _ = self.count_color_pixels(converted_img, contour)\r\n            if grey_count >= white_count: return None, None\r\n            return contour, thresh\r\n        if hierarchy is None: return None, None\r\n        contour = utils.get_target_contour(contours, hierarchy, False)\r\n        if contour is None: return None, None\r\n        return contour, thresh\r\n    \r\n    def is_yellow(self, b, g, r):\r\n        """Checks if the given BGR values correspond to yellow color."""\r\n        b = int(b)\r\n        g = int(g)\r\n        r = int(r)\r\n        if b < 3 and r > 205 and r < 209 and g > 205 and g < 209: return True\r\n        return False\r\n    \r\n    def is_red(self, b, g, r):\r\n        """Checks if the given BGR values correspond to red color."""\r\n        b = int(b)\r\n        g = int(g)\r\n        r = int(r)\r\n        if g < 3 and b < 3 and r > 205 and r < 209: return True\r\n        return False\r\n    \r\n    def is_blue(self, b, g, r):\r\n        """Checks if the given BGR values correspond to blue color."""\r\n        if r < 3 and g < 3 and b > 205 and b < 209: return True\r\n        return False\r\n\r\n    def is_green(self, b, g, r):\r\n        """Checks if the given BGR values correspond to green color."""\r\n        if r < 3 and b < 3 and g > 205 and g < 209: return True\r\n        return False\r\n    \r\n    def is_grey(self, b, g, r):\r\n        """Checks if the given BGR values correspond to grey color."""\r\n        if b > 130 and g > 130 and r > 130 and b < 150 and g < 150 and r < 150: return True\r\n        return False\r\n    \r\n    def is_white(self, b, g, r):\r\n        """Checks if the given BGR values correspond to white color."""\r\n        if b > 200 and g > 200 and r > 200: return True\r\n        return False\r\n    \r\n    def is_black(self, b, g, r):\r\n        """Checks if the given BGR values correspond to black color."""\r\n        if b <= 50 and g <= 50 and r <= 50: return True\r\n        return False\r\n    \r\n    def get_colour_score(self, name):\r\n        """Returns the score associated with a given color name."""\r\n        value = ColourScores[name].value\r\n        return value\r\n    \r\n    def count_continuous_obs_pixels(self, img):\r\n        """Counts the number of continuous pixels of the same color as the central pixel in the horizontal direction."""\r\n        center_y ,center_x =  img.shape[0] // 2,  img.shape[1] // 2\r\n        \r\n        central_pixel = img[center_y, center_x]\r\n        b_ref, g_ref, r_ref = central_pixel[:3]\r\n        \r\n        obstacle_px = 0\r\n\r\n        if not self.is_exclude_color(b_ref, g_ref, r_ref):\r\n            obstacle_px += 1\r\n\r\n        #LEFT\r\n        for x in range(center_x - 1, -1, -1):\r\n            b, g, r = img[center_y, x][:3]\r\n            \r\n            if b == b_ref and g == g_ref and r == r_ref:\r\n                if not self.is_exclude_color(b, g, r):\r\n                    # print(f"LEFT: B {b}  G {g}  R {r}" )\r\n                    obstacle_px += 1\r\n            else:\r\n                break\r\n        #RIGHT\r\n        for x in range(center_x + 1, img.shape[1]):\r\n            b, g, r = img[center_y, x][:3]\r\n            \r\n            if b == b_ref and g == g_ref and r == r_ref:\r\n                if not self.is_exclude_color(b, g, r):\r\n                    # print(f"RIGHT: B {b}  G {g}  R {r}" )\r\n                    obstacle_px += 1\r\n            else:\r\n                break\r\n        return obstacle_px    \r\n\r\n    def is_exclude_color(self, b, g, r):\r\n        """Checks if the given BGR values correspond to excluded colors or specific conditions."""\r\n        excluded_colors = {(207, 0, 0), (0, 207, 0), (0, 0, 207), (0, 207, 207), (221, 221, 221), (207, 207, 207), (213, 211, 210), (242, 240, 240), (128, 196, 196)} # Directions colors\r\n        return (b, g, r) in excluded_colors or ((r < g) & (g < b) & (r < (g * 0.625)) & (r > ( g * 0.45)) & (g >= 0.9 * b)) or (b <= 3) & (g <= 3) & (r <= 3)\r\n    \r\n    def clean_walls(self, img):\r\n        """It cleans the walls of the image, leaving only the crucial colors for the victim detection."""\r\n        \r\n        if img is None: return None\r\n        if img.size == 0: return None\r\n\r\n        b = img[...,0]\r\n        g = img[...,1]\r\n        r = img[...,2]\r\n\r\n        is_wall = (r < g) & (g < b) & (r < (g * 0.625)) & (r > ( g * 0.45)) & (g >= 0.9 * b)\r\n        channels = img.shape[2] if img.ndim == 3 else 1\r\n        fill_black = (0, 0, 0, 255) if channels == 4 else (0, 0, 0)\r\n\r\n        aux_img = img.copy()\r\n        aux_img[is_wall] = fill_black\r\n        return aux_img\r\n    \r\n    def thresh_with_given_colour(self, img, color):\r\n        """It thresholds the image, setting as white the pixels that match the given color and as black the rest."""\r\n        if img is None: return None\r\n        if img.size == 0: return None\r\n\r\n        b = img[...,0]\r\n        g = img[...,1]\r\n        r = img[...,2]\r\n\r\n        values = color.value\r\n        given_r, given_g, given_b = values[0], values[1], values[2]\r\n\r\n        is_color = (b == given_b) & (g == given_g) & (r == given_r)\r\n\r\n        channels = img.shape[2] if img.ndim == 3 else 1\r\n        fill_white = (255, 255, 255, 255) if channels == 4 else (255, 255, 255)\r\n        fill_black = (0, 0, 0, 255) if channels == 4 else (0, 0, 0)\r\n\r\n        aux_img = np.full_like(img, fill_black, dtype=np.uint8)\r\n        aux_img[is_color] = fill_white\r\n\r\n        grey = cv2.cvtColor(aux_img, cv2.COLOR_BGR2GRAY)\r\n        _, thresh = cv2.threshold(grey, 125, 255, cv2.THRESH_BINARY)\r\n        return thresh\r\n\r\n    def threshold_image(self, img):\r\n        """An own thresh that is adptative to the simulation\'s noise, setting as white crucial color pixels\r\n        and as black the not crucial ones for the victims detection. NumPy operartors are used due to its efficiency \r\n        (faster than Python loops)."""\r\n        if img is None: return None\r\n        if img.size == 0: return None\r\n\r\n        b = img[...,0]\r\n        g = img[...,1]\r\n        r = img[...,2]\r\n\r\n        is_wall = (r < g) & (g < b) & (r < (g * 0.625)) & (r > ( g * 0.45)) & (g >= 0.9 * b)\r\n        is_black = (b <= 50) & (g <= 50) & (r <= 50)\r\n        is_not_crucial = is_wall | is_black # Is crucial: yellow, red, white\r\n\r\n        channels = img.shape[2] if img.ndim == 3 else 1\r\n        fill_white = (255, 255, 255, 255) if channels == 4 else (255, 255, 255)\r\n        fill_black = (0, 0, 0, 255) if channels == 4 else (0, 0, 0)\r\n\r\n        aux_img = np.full_like(img, fill_white, dtype=np.uint8)\r\n        aux_img[is_not_crucial] = fill_black\r\n\r\n        grey = cv2.cvtColor(aux_img, cv2.COLOR_BGR2GRAY)\r\n        _, thresh = cv2.threshold(grey, 125, 255, cv2.THRESH_BINARY)\r\n        # self.debug_show(thresh, "thresh")\r\n        return thresh\r\n\r\n    def threshold_cognitive_image(self, img):\r\n        """An own thresh that is adptative to the simulation\'s noise, setting as white crucial color pixels\r\n        and as black the not crucial ones for cognitive targets detection. NumPy operartors are used due to its \r\n        efficiency (faster than Python loops)."""\r\n        if img is None: return None\r\n        if img.size == 0: return None\r\n\r\n        b = img[...,0]\r\n        g = img[...,1]\r\n        r = img[...,2]\r\n\r\n        is_wall = (r < g) & (g < b) & (r < (g * 0.625)) & (r > ( g * 0.45)) & (g >= 0.9 * b)\r\n        is_white = (b > 190) & (g > 190) & (r > 190)\r\n        is_sky = (r < g) & (g < b) & (g < b * 0.76) & (g > b * 0.60)\r\n        is_not_crucial = is_wall | is_white | is_sky # | is_black # Is crucial: yellow, red, white ADDED: blue, green\r\n\r\n        is_red = (r > 205) & (r < 209) & (g < 3) & (b < 3)\r\n        is_yellow = (r > 205) & (r < 209) & (g > 205) & (g < 209) & (b < 3)\r\n        is_blue = (b > 205) & (b < 209) & (g < 3) & (r < 3)\r\n        is_green = (g > 205) & (g < 209) & (r < 3) & (b < 3)\r\n        is_black = (b <= 50) & (g <= 50) & (r <= 50)\r\n        is_crucial = is_red | is_yellow | is_blue | is_green | is_black\r\n\r\n        channels = img.shape[2] if img.ndim == 3 else 1\r\n        fill_white = (255, 255, 255, 255) if channels == 4 else (255, 255, 255)\r\n        fill_black = (0, 0, 0, 255) if channels == 4 else (0, 0, 0)\r\n\r\n        # aux_img = np.full_like(img, fill_white, dtype=np.uint8)\r\n        # aux_img[is_not_crucial] = fill_black\r\n\r\n        aux_img = np.full_like(img, fill_black, dtype=np.uint8)\r\n        aux_img[is_crucial] = fill_white\r\n        aux_img[is_wall] = fill_black\r\n\r\n        grey = cv2.cvtColor(aux_img, cv2.COLOR_BGR2GRAY)\r\n        _, thresh = cv2.threshold(grey, 125, 255, cv2.THRESH_BINARY)\r\n        # self.debug_show(thresh, "thresh")\r\n        return thresh\r\n    \r\n    def get_contour_centre(self, img, analyzing_after_placing = False, is_zoomed_img = False, is_cognitive = False):\r\n        """It returns the centre of the contour, if it is not found, it returns None."""\r\n        if not is_cognitive:\r\n            contour, _ = self.clean_image_with_own_thresh(img, is_zoomed_img = is_zoomed_img, debug_show = False)\r\n            # print(f"Is contour None? {contour is None}")\r\n        else:\r\n            # print(f"Is cognitive, using different cleaning image!")\r\n            contour, _ = self.clean_cognitive_image_with_own_thresh(img)\r\n        if contour is None and analyzing_after_placing:\r\n            if not is_cognitive:\r\n                thresh = self.threshold_image(img)\r\n            else:\r\n                thresh = self.threshold_cognitive_image(img)\r\n            contours, _ = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n            contour = self.select_biggest_contour(contours)\r\n            if contour is None: return None\r\n        \r\n        contour_centre = self.obtain_contours_centre(contour)\r\n        # print(f"Contour centre: {contour_centre}")\r\n        return contour_centre\r\n        \r\n    def clean_image_with_own_thresh(self, converted_img, analyzing_after_placing = False, is_zoomed_img = False, debug_show = False):\r\n        """Same logic that clean_image but using our own thresh, this step is used when analyzing the complete image and\r\n        when using the is_image, to detect if the image is a sign or not."""\r\n        aux_img = converted_img.copy()\r\n        if converted_img is None:\r\n            return None, None\r\n        thresh = self.threshold_image(converted_img)\r\n        if debug_show:\r\n            self.debug_show(thresh, "thresh")\r\n        contours, hierarchy = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n        if contours is None: return None, None\r\n\r\n        # print(f"Contours {len(contours)}")\r\n        """If theres no hierarchy to analyze (only one contour), we skip the hierarchy-based contour selection"""\r\n        if len(contours) == 1:\r\n            # print("ACAACA")\r\n            contour = contours[0]\r\n            contour = self.discard_contour(converted_img, contour, is_zoomed_img = is_zoomed_img)\r\n            if contour is None: return None, None\r\n            if debug_show:\r\n                aux_img = cv2.drawContours(aux_img, [contour], -1, (0, 255, 0), 1)\r\n                self.debug_show(aux_img, "contour")\r\n            return contour, thresh\r\n        \r\n        if hierarchy is None: return None, None\r\n        contour = utils.get_target_contour(contours, hierarchy, False)\r\n        if contour is None: \r\n            biggest_contour = self.select_biggest_contour(contours)\r\n            if debug_show:\r\n                cv2.drawContours(aux_img, [biggest_contour], -1, (0, 255, 0), 1)\r\n                self.debug_show(aux_img, "biggest_contour")\r\n            contour = self.discard_contour(converted_img, biggest_contour, is_zoomed_img = is_zoomed_img)\r\n            if contour is None and not analyzing_after_placing:\r\n                return None, None\r\n        return contour, thresh\r\n        \r\n        \r\n    def clean_cognitive_image_with_own_thresh(self, converted_img, analyzing_after_placing = False):\r\n        """Same logic that clean_image but using our own thresh, this step is used when analyzing the complete image and\r\n        when using the is_image, to detect if the image is a sign or not."""\r\n        aux_img = converted_img.copy()\r\n        if converted_img is None:\r\n            return None, None\r\n        thresh = self.threshold_cognitive_image(converted_img)\r\n        # self.debug_show(thresh, "thresh")\r\n\r\n        contours, hierarchy = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n        if contours is None: return None, None\r\n\r\n        # print(f"Contours {len(contours)}")\r\n        """If theres no hierarchy to analyze (only one contour), we skip the hierarchy-based contour selection"""\r\n        if len(contours) == 1:\r\n            # print(f"Theres only one contour, hierarchy: {hierarchy}")\r\n            # print("ACAACA")\r\n            contour = contours[0]\r\n            contour = self.discard_contour(converted_img, contour)\r\n            if contour is None: return None, None\r\n            # aux_img = cv2.drawContours(aux_img, [contour], -1, (0, 255, 0), 1)\r\n            # self.debug_show(aux_img, "contour")\r\n            return contour, thresh\r\n        \r\n        if hierarchy is None: return None, None\r\n        contour = utils.get_target_contour(contours, hierarchy, False)\r\n        if contour is None:\r\n            biggest_contour = self.select_biggest_contour(contours)\r\n            cv2.drawContours(aux_img, [biggest_contour], -1, (0, 255, 0), 1)\r\n            # self.debug_show(aux_img, "biggest_contour")\r\n            contour = self.discard_contour(converted_img, biggest_contour)\r\n            if contour is None and not analyzing_after_placing:\r\n                return None, None\r\n        return contour, thresh\r\n    \r\n    def clean_contour(self, contour, img):\r\n        """Cleans the contour, obtaining the four corners of the contour and returning a cleaned image with only the area of the contour."""\r\n        if contour is None: return None\r\n        if img is None: return None\r\n\r\n        aux_img = img.copy()\r\n        pts = contour.reshape(-1, 2) # Reshape the contour to a 2D array of points\r\n\r\n        top_left_corner = pts[np.argmin(pts.sum(axis=1))] # The top-left corner will have the smallest sum of x and y coordinates\r\n        top_right_corner = pts[np.argmin(np.diff(pts, axis=1))] # The top-right corner will have the smallest difference between x and y coordinates\r\n        bottom_right_corner = pts[np.argmax(pts.sum(axis=1))] # The bottom-right corner will have the largest sum of x and y coordinates\r\n        bottom_left_corner = pts[np.argmax(np.diff(pts, axis=1))] # The bottom-left corner will have the largest difference between x and y coordinates\r\n        # print(f"Top left corner: {top_left_corner}, Top right corner: {top_right_corner}, Bottom left corner: {bottom_left_corner}, Bottom right corner: {bottom_right_corner}")\r\n\r\n        aux_img = cv2.circle(aux_img, top_left_corner, 1, (255, 0, 0), -1)\r\n        aux_img = cv2.circle(aux_img, top_right_corner, 1, (0, 255, 0), -1)\r\n        aux_img = cv2.circle(aux_img, bottom_left_corner, 1, (0, 0, 255), -1)\r\n        aux_img = cv2.circle(aux_img, bottom_right_corner, 1, (255, 0, 255), -1)\r\n        # self.debug_show(aux_img, "corners")\r\n\r\n        if top_left_corner[1] > top_right_corner[1]:\r\n            top_right_corner = (top_right_corner[0], top_left_corner[1])\r\n        else:\r\n            top_left_corner = (top_left_corner[0], top_right_corner[1])\r\n\r\n        if bottom_left_corner[1] < bottom_right_corner[1]:\r\n            bottom_right_corner = (bottom_right_corner[0], bottom_left_corner[1])\r\n        else:\r\n            bottom_left_corner = (bottom_left_corner[0], bottom_right_corner[1])\r\n\r\n        if top_left_corner[0] > bottom_left_corner[0]:\r\n            bottom_left_corner = (top_left_corner[0], bottom_left_corner[1])\r\n        else:\r\n            top_left_corner = (bottom_left_corner[0], top_left_corner[1])\r\n\r\n        if top_right_corner[0] < bottom_right_corner[0]:\r\n            bottom_right_corner = (top_right_corner[0], bottom_right_corner[1])\r\n        else:\r\n            top_right_corner = (bottom_right_corner[0], top_right_corner[1])\r\n\r\n        cleaned_img = img[top_left_corner[1]:bottom_left_corner[1], top_left_corner[0]:top_right_corner[0]]\r\n        cleaned_contour = np.array([top_left_corner, top_right_corner, bottom_right_corner, bottom_left_corner])\r\n        return cleaned_img, cleaned_contour\r\n    \r\n    def discard_contour(self, converted_img, contour, is_zoomed_img = False):\r\n        """Discards contours thtat are from signs already detected based on the color pixel counts and relations between them."""\r\n        yellow_count, red_count, white_count, black_count, grey_count, blue_count, green_count = self.count_color_pixels(converted_img, contour)\r\n        if (grey_count >= white_count) and (yellow_count == 0 and red_count == 0 and blue_count == 0 and green_count == 0): # Victim already seen\r\n            return None\r\n        if (yellow_count >= 1 or red_count >= 1 or blue_count >= 1 or green_count >= 1) and (white_count != 0): # A cognitive with white for us is a cognitive already seen\r\n            return None\r\n        if (white_count != 0) and (black_count == 0) and not is_zoomed_img:\r\n            return None\r\n        return contour\r\n    \r\n    def clean_letter(self, img, thresh):\r\n        """It looks for the contour with parent and no children."""\r\n        aux_img = img.copy()\r\n        contours, hierarchy = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n        if hierarchy is None: return None\r\n        contour = utils.get_target_contour(contours, hierarchy, True)\r\n        if contour is None: return None\r\n        return contour\r\n    \r\n    def select_biggest_contour(self, contours):\r\n        """Selects the biggest contour from a list of contours."""\r\n        if contours is None or len(contours) == 0: return None\r\n        biggest_contour = max(contours, key=cv2.contourArea)\r\n        return biggest_contour\r\n    \r\n    def count_black_white_pixels(self, img):\r\n        """Returns the amount of black and white pixels in the image."""\r\n        black_pixels = np.count_nonzero(img == 0)\r\n        white_pixels = np.count_nonzero(img == 255)\r\n        return black_pixels, white_pixels\r\n\r\n    def squares_pixel_count(self, upper_square, middle_square, lower_square, left_square, right_square, upper_left_square, upper_right_square, lower_left_square, lower_right_square):\r\n        """Splits the letter contour in 9 equal squares that are used to analize the letter."""\r\n        upper_pixels = self.get_pixels_percentages(upper_square)\r\n        middle_pixels = self.get_pixels_percentages(middle_square)\r\n        lower_pixels = self.get_pixels_percentages(lower_square)\r\n        left_pixels = self.get_pixels_percentages(left_square)\r\n        right_pixels = self.get_pixels_percentages(right_square)\r\n        upper_left_pixels = self.get_pixels_percentages(upper_left_square)\r\n        upper_right_pixels = self.get_pixels_percentages(upper_right_square)\r\n        lower_left_pixels = self.get_pixels_percentages(lower_left_square)\r\n        lower_right_pixels = self.get_pixels_percentages(lower_right_square)\r\n\r\n        return upper_pixels, middle_pixels, lower_pixels, left_pixels, right_pixels, upper_left_pixels, upper_right_pixels, lower_left_pixels, lower_right_pixels\r\n\r\n    def rotate_image(self, img, angle):\r\n        """Rotates the image to a given angle."""\r\n        height, width = img.shape[0], img.shape[1]\r\n        M = cv2.getRotationMatrix2D((width / 2, height / 2), angle, 1)\r\n        rotated_image = cv2.warpAffine(img, M, (width, height))\r\n        contour, _ = self.clean_image_with_own_thresh(rotated_image)\r\n        if contour is None: return None\r\n        return rotated_image\r\n    \r\n    def straighten_image(self, img, contour):\r\n        """Straightens the image based on the contour\'s convex hull."""\r\n        if contour is None: return None\r\n        hull = cv2.convexHull(contour)\r\n        # Enderezar la imagen usando los puntos del casco convexos\r\n        src_pts = np.float32(self.get_contour_corners(hull))\r\n\r\n        epsilon = 0.01 * cv2.arcLength(hull, closed = True)\r\n        approx = cv2.approxPolyDP(hull, epsilon, closed = True)\r\n        if approx is not None and len(approx) == 4:\r\n            for factor in [0.03, 0.05, 0.07, 0.1]:\r\n                epsilon = factor * cv2.arcLength(hull, closed=True)\r\n                approx = cv2.approxPolyDP(hull, epsilon, closed=True)\r\n                if len(approx) == 4:\r\n                    break\r\n\r\n        x, y, w, h = cv2.boundingRect(contour)\r\n        dst_pts = np.float32([\r\n            [x, y ], # Top-left corner\r\n            [x + w - 1, y], # Top-right corner\r\n            [x + w - 1, y + h - 1], # Bottom-right corner\r\n            [x, y + h - 1], # Bottom-left corner\r\n        ])\r\n\r\n        M = cv2.getPerspectiveTransform(src_pts, dst_pts)\r\n        warped = cv2.warpPerspective(img, M, (img.shape[1], img.shape[0]))\r\n        return warped\r\n\r\n    def return_victim_letter(self, img, contour):\r\n        """Victims detection logic"""\r\n        if contour is None: return None\r\n        if img is None: return None\r\n        aux_img = img.copy()\r\n\r\n        # 1) Rotate the image if the contour\'s angle is not a multiple of 90 degrees, otherwise, we keep the original image        \r\n        angle = cv2.minAreaRect(contour)[2]\r\n        if not utils.near_multiple(angle, 90, 2):\r\n            rotated_image = self.rotate_image(img, angle)\r\n            if rotated_image is None: return None\r\n        else: rotated_image = img.copy()\r\n\r\n        # 2) Clean the walls of the image and then obtain the new letter contour and the new thresholded image.\r\n        image_with_no_wall = self.clean_walls(rotated_image)\r\n        raw_letter_contour, thresh = self.clean_image(image_with_no_wall, 100)\r\n\r\n        # 3) Straighten the image if necessary (contour is considerably deformed). If straightened, clean again the image.\r\n        if self.needs_contour_be_straightened(raw_letter_contour):\r\n            image_with_no_wall = self.straighten_image(image_with_no_wall, raw_letter_contour)\r\n            raw_letter_contour, thresh = self.clean_image(image_with_no_wall, 100)\r\n\r\n        # 4) Clean the contour to obtain the four corners of the letter and crop the image to only have the letter.\r\n        if thresh is None: return None\r\n        _, letter_contour = self.clean_contour(raw_letter_contour, image_with_no_wall)\r\n        if letter_contour is None: return None\r\n\r\n        # 5) Split the letter contour in 9 (as a tic-tac-toe) squares and count the black and white pixels in each square.\r\n        squares = self.get_letter_regions(thresh, letter_contour)\r\n        if squares is None: return None\r\n        upper_square, middle_square, lower_square, left_square, right_square, upper_left_square, upper_right_square, lower_left_square, lower_right_square = squares\r\n        upper_pixels, middle_pixels, lower_pixels, left_pixels, right_pixels, upper_left_pixels, upper_right_pixels, lower_left_pixels, lower_right_pixels  = self.squares_pixel_count(upper_square, middle_square, lower_square, left_square, right_square, upper_left_square, upper_right_square, lower_left_square, lower_right_square)\r\n \r\n        # 6) Based on the pixel counts, we determine the letter (U, H, S) that is represented by the contour.\r\n        letter = self.get_letter(upper_pixels, middle_pixels, lower_pixels, left_pixels, right_pixels, upper_left_pixels, upper_right_pixels, lower_left_pixels, lower_right_pixels)\r\n        if letter is None: return None\r\n        return letter\r\n\r\n    def get_letter(self, upper_pixels, middle_pixels, lower_pixels, left_pixels, right_pixels, upper_left_pixels, upper_right_pixels, lower_left_pixels, lower_right_pixels):\r\n        """Determines the letter (U, H, S) basing on the amount of white pixels in the middle square and the relation between black and white\r\n        pixels of each top/bottom corner square."""\r\n        middle_white_pixels = middle_pixels["White"] if middle_pixels is not None and "White" in middle_pixels else 0\r\n        upper_left_black_pixels = upper_left_pixels["Black"] if upper_left_pixels is not None and "Black" in upper_left_pixels else 0\r\n        upper_right_black_pixels = upper_right_pixels["Black"] if upper_right_pixels is not None and "Black" in upper_right_pixels else 0\r\n        lower_left_black_pixels = lower_left_pixels["Black"] if lower_left_pixels is not None and "Black" in lower_left_pixels else 0\r\n        lower_right_black_pixels = lower_right_pixels["Black"] if lower_right_pixels is not None and "Black" in lower_right_pixels else 0\r\n        \r\n        if middle_white_pixels > 90: return \'U\'\r\n        black_pixels = sorted([upper_left_black_pixels, upper_right_black_pixels, lower_left_black_pixels, lower_right_black_pixels], reverse = True)\r\n        biggest_black_average = (black_pixels[0] + black_pixels[1]) / 2\r\n        smallest_black_average = (black_pixels[2] + black_pixels[3]) / 2\r\n        diff = abs(biggest_black_average - smallest_black_average)\r\n        if diff <= 15: return \'H\'\r\n        return \'S\'\r\n\r\n    def get_pixels_percentages(self, region):\r\n        """Returns the white and black percentages from a dict."""\r\n        pixels = {}\r\n        black_pixels, white_pixels = self.count_black_white_pixels(region)\r\n        black_pix_per, white_pix_per = utils.get_percentage(black_pixels, white_pixels)\r\n        if black_pix_per is None: return None\r\n        if white_pix_per is None: return None\r\n        if black_pix_per == 0 and white_pix_per == 0: return None\r\n        pixels["Black"] = black_pix_per\r\n        pixels["White"] = white_pix_per\r\n        if pixels is None: return None\r\n        return pixels\r\n\r\n    def get_letter_regions(self, thresh, letter_contour):\r\n        """Slices the letter contour in 5 regions (upper, middle, lower, left and right) to analize the letter."""\r\n        if thresh is None: return None\r\n        copy = thresh.copy()\r\n        x, y, width, height = cv2.boundingRect(letter_contour)\r\n \r\n        rect = thresh[y: y + height, x: x + width]\r\n        \r\n        if abs(rect.shape[0] - rect.shape[1]) > 10: return None\r\n        if rect.shape[0] * rect.shape[1] == 0: return None\r\n\r\n        black_pixels = np.count_nonzero(rect == 0)\r\n        if black_pixels == 0: return None\r\n \r\n        upper_square = thresh[y: y + int(height / 3), x + int(width / 3): x + int(2 * (width / 3))]\r\n        middle_square = thresh[y + int(height / 3): y + int(2 * (height / 3)),x + int(width / 3): x + int(2 * (width / 3))]\r\n        lower_square = thresh[y + int(2 * (height / 3)): y + height, x + int(width / 3): x + int(2 * (width / 3))]\r\n        left_square = thresh[y + int(height / 3): y + int(2 * (height / 3)), x:x + int(width / 3)]\r\n        right_square = thresh[y + int(height / 3): y + int(2 * (height / 3)), x + int(2 * (width / 3)): x + width]\r\n        upper_left_square = thresh[y: y + int(height / 3), x: x + int(width / 3)]\r\n        upper_right_square = thresh[y: y + int(height / 3), x + int(2 * (width / 3)): x + width]\r\n        lower_left_square = thresh[y + int(2 * (height / 3)): y + height, x: x + int(width / 3)]\r\n        lower_right_square = thresh[y + int(2 * (height / 3)): y + height, x + int(2 * (width / 3)): x + width]\r\n\r\n        return upper_square, middle_square, lower_square, left_square, right_square, upper_left_square, upper_right_square, lower_left_square, lower_right_square    \r\n\r\n    def get_min_circle_contour(self, img, r, g, b):\r\n        """Obstains the first concentric circle contour of the cognitive target (central ring)."""\r\n        if (r, g, b) not in ColourValues._value2member_map_:\r\n            print(f"Color values: R={r}, G={g}, B={b} not found in ColourValues enum")\r\n            return None\r\n        \r\n        min_circle_tresh = self.thresh_with_given_colour(img, ColourValues((r, g, b)))\r\n        if min_circle_tresh is None: return None\r\n\r\n        min_circle_contours, hierarchy = cv2.findContours(min_circle_tresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)\r\n        if min_circle_contours is None or len(min_circle_contours) == 0: return None\r\n        if len(min_circle_contours) == 1:\r\n            min_circle_contour = min_circle_contours[0]\r\n        else:\r\n            min_circle_contour = utils.get_target_contour(min_circle_contours, hierarchy, is_letter_contour=True)\r\n        return min_circle_contour\r\n    \r\n\r\n    def get_analyzing_side_data(self, contour, cx):\r\n        """Determines which side of the contour is bigger and better for analyzing. Returns a boolean for \r\n        each side and the radius of the contour."""\r\n        count_right_side = False\r\n        count_left_side = False\r\n\r\n        rightmost = tuple(contour[contour[:,:,0].argmax()][0])\r\n        leftmost = tuple(contour[contour[:,:,0].argmin()][0])\r\n\r\n        if self.contour_on_left_border(contour):\r\n            count_right_side = True\r\n        elif self.contour_on_right_border(contour):\r\n            count_left_side = True\r\n        else:\r\n            right_diff = abs(rightmost[0] - cx)\r\n            left_diff = abs(leftmost[0] - cx)\r\n            if right_diff > left_diff:\r\n                count_right_side = True\r\n            else:\r\n                count_left_side = True\r\n\r\n        if count_left_side:\r\n            radius = cx - leftmost[0]\r\n        else:\r\n            radius = rightmost[0] - cx\r\n\r\n        return count_left_side, count_right_side, radius\r\n    \r\n    def get_key_points_data(self, img, radius, cx, cy, count_left_side, count_right_side):\r\n        """Obtains the five key points of the cognitive target to analyze its color values."""\r\n        step = radius / 5\r\n        points = []\r\n        for i in range(5):\r\n            point_data = {}\r\n            if count_left_side:\r\n                x = int((cx - radius) + (i + 0.5) * step)\r\n            elif count_right_side:\r\n                x = int((cx + radius) - (i + 0.5) * step)\r\n            point = (x, int(cy))\r\n            pixel = img[point[1], point[0]]\r\n            b, g, r = pixel[:3]\r\n            point_data[point] = (r, g, b)\r\n            points.append(point_data)\r\n        return points\r\n    \r\n    def get_sum_values(self, points):\r\n        """Calculates the sum of colour scores for the given points."""\r\n        sum_value = 0\r\n        for point_data in points:\r\n            for value in point_data.values():\r\n                r, g, b = value\r\n                if (r, g, b) not in ColourValues._value2member_map_:\r\n                    continue\r\n                colour_name_in_enum = ColourValues((r, g, b)).name\r\n                value = self.get_colour_score(colour_name_in_enum)\r\n                sum_value += value \r\n        return sum_value\r\n\r\n    def get_cognitive_letter(self, count):\r\n        """Determines the cognitive letter based on the sum of colour scores."""\r\n        if count == 0:\r\n            return \'F\'\r\n        elif count == 1:\r\n            return \'P\'\r\n        elif count == 2:\r\n            return \'C\'\r\n        elif count == 3:\r\n            return \'O\'\r\n        else:\r\n            return \'Z\' # NOTE (Martu): Fake signs representation\r\n        \r\n    def return_cognitive_letter(self, img):\r\n        """Cognitive target detection logic"""\r\n        if img is None: return None\r\n        aux_img = img.copy()\r\n\r\n        # 1) Clean the image to obtain the contour of the cognitive target.\r\n        contour, thresh = self.clean_cognitive_image_with_own_thresh(img)\r\n        if contour is None: return None\r\n\r\n        # 2) Verify if the sign is simetrical enough to be analyzed.\r\n        rect = cv2.minAreaRect(contour)\r\n        if rect is None: return None\r\n        (x, y), (w, h), angle = rect\r\n        print(f"Diff between width and height: {abs(w - h)}")\r\n        if abs(w - h) > 8: return None\r\n\r\n        # 3) Obtain the minimum enclosing circle of the contour to determine its center and radius.\r\n        circ = cv2.minEnclosingCircle(contour)\r\n        if circ is None: return None\r\n        center, radius = circ\r\n\r\n        # 4) Get the color values of the center pixel of the cognitive target.\r\n        center_b = img[int(center[1]), int(center[0]), 0]\r\n        center_g = img[int(center[1]), int(center[0]), 1]\r\n        center_r = img[int(center[1]), int(center[0]), 2]\r\n\r\n        # 5) Obtain the contour of the minimum enclosing circle of the cognitive target based on the center color values.\r\n        min_circle_contour = self.get_min_circle_contour(img, center_r, center_g, center_b)\r\n        if min_circle_contour is None: return None\r\n\r\n        # 6) Get the bounding rectangle of the minimum enclosing circle contour to determine its exact center.\r\n        rect = cv2.boundingRect(min_circle_contour)\r\n        if rect is None: return None\r\n        x, y, w, h = rect # Corners, width and height of the bounding rectangle\r\n\r\n        cx, cy = x + w / 2, y + h / 2\r\n\r\n        # 7) Determine which side of the contour is bigger and better for analyzing.\r\n        count_left_side, count_right_side, radius = self.get_analyzing_side_data(contour, cx)\r\n\r\n        # 8) Obtain the five key points of the cognitive target to analyze its color values.\r\n        points = self.get_key_points_data(img, radius, cx, cy, count_left_side, count_right_side)\r\n\r\n        # 9) Calculate the sum of color scores for the given points.\r\n        sum_value = self.get_sum_values(points)\r\n\r\n        cognitive_letter = self.get_cognitive_letter(sum_value)\r\n        return cognitive_letter\r\n\r\n\r\n    def count_color_pixels(self, img, contour):\r\n        """Counts the color pixels inside a contour, returns the count of yellow, red, white, black and grey pixels."""\r\n        if contour is None: return None\r\n        if img is None: return None\r\n\r\n        area = cv2.contourArea(contour)\r\n        # print(f"Contour area: {area}")\r\n        if area < MIN_AREA or len(contour) < 3:\r\n            return 0, 0, 0, 0, 0, 0, 0\r\n        yellow_count, red_count, black_count, white_count, grey_count, blue_count, green_count = 0, 0, 0, 0, 0, 0, 0\r\n        for x in range(img.shape[0]):\r\n            for y in range(img.shape[1]):\r\n                if cv2.pointPolygonTest(contour, (x, y), False) > 0:\r\n                    pixel = img[y, x]\r\n                    b, g, r = pixel[:3]\r\n                    if self.is_white(b, g, r):\r\n                        white_count += 1\r\n                    elif self.is_black(b, g, r):\r\n                        black_count += 1\r\n                    elif self.is_grey(b, g, r):\r\n                        grey_count += 1\r\n                    elif self.is_red(b, g, r):\r\n                        red_count += 1\r\n                        # print(f"Pixel at ({x}, {y}): B={b}, G={g}, R={r}")\r\n                    elif self.is_yellow(b, g, r):\r\n                        yellow_count += 1\r\n                        # print(f"Pixel at ({x}, {y}): B={b}, G={g}, R={r}")\r\n                    elif self.is_blue(b, g, r):\r\n                        blue_count += 1\r\n                    elif self.is_green(b, g, r):\r\n                        green_count += 1\r\n        return yellow_count, red_count, white_count, black_count, grey_count, blue_count, green_count\r\n\r\n    def contour_on_lateral_border(self, cnt):\r\n        """Checks if a contour is touching any lateral border."""\r\n        leftmost = tuple(cnt[cnt[:,:,0].argmin()][0])\r\n        rightmost = tuple(cnt[cnt[:,:,0].argmax()][0])\r\n        if leftmost[0] == 0 or leftmost[0] == 39: return True\r\n        if rightmost[0] == 0 or rightmost[0] == 39: return True\r\n        return False\r\n\r\n    def contour_on_left_border(self, cnt):\r\n        """Checks if a contour is touching the left border."""\r\n        leftmost = tuple(cnt[cnt[:,:,0].argmin()][0])\r\n        if leftmost[0] == 0 or leftmost[0] == 39: return True\r\n        return False\r\n    \r\n    def contour_on_right_border(self, cnt):\r\n        """Checks if a contour is touching the right border."""\r\n        rightmost = tuple(cnt[cnt[:,:,0].argmax()][0])\r\n        if rightmost[0] == 0 or rightmost[0] == 39: return True\r\n        return False   \r\n    \r\n    def count_image_color_pixels(self, img):\r\n        """Counts the color pixels in the image, returns the count of yellow, red, white, black, grey and wall pixels."""\r\n        if img is None or img.size == 0:\r\n            return None\r\n\r\n        b = img[..., 0]\r\n        g = img[..., 1]\r\n        r = img[..., 2]\r\n\r\n        is_wall = (((b > 125) & (b < 165) & (g > 115) & (g < 150) & (r > 55) & (r < 75)) | ((b > 25) & (b < 65) & (g > 25) & (g < 65) & (r > 15) & (r < 45))) # | ((b > 27) & (b < 37) & (g > 25) & (g < 35) & (r > 13) & (r < 23)))\r\n        is_white = (b > 200) & (g > 200) & (r > 200)\r\n        is_black = (b <= 25) & (g <= 25) & (r <= 25)\r\n        is_grey = (b > 130) & (g > 130) & (r > 130) & (b < 150) & (g < 150) & (r < 150) # | (b - r < 5) & (g - r < 5) & (b - g < 5)\r\n        # NOTE (Martu): For no detecting obstacles and/or redetecting!\r\n        is_red = (b < 5) & (g < 5) & (r > 205) & (r < 209)\r\n        is_yellow = (b < 5) & (g > 205) & (r > 205) & (g < 209) & (r < 209)\r\n        is_green = (b < 5) & (g > 205) & (r < 5) & (g < 209)\r\n        is_blue = (b > 205) & (g < 5) & (r < 5) & (b < 209)\r\n\r\n        yellow_count = np.count_nonzero(is_yellow)\r\n        red_count = np.count_nonzero(is_red)\r\n        white_count = np.count_nonzero(is_white)\r\n        black_count = np.count_nonzero(is_black)\r\n        grey_count = np.count_nonzero(is_grey)\r\n        wall_count = np.count_nonzero(is_wall)\r\n        blue_count = np.count_nonzero(is_blue)\r\n        green_count = np.count_nonzero(is_green)\r\n\r\n        return yellow_count, red_count, white_count, black_count, grey_count, wall_count, blue_count, green_count\r\n    \r\n    def is_image_zoomed_in(self, img):\r\n        """Evaluates if the image is or not a zoomed in sign."""\r\n        yellow_count, red_count, white_count, black_count, _, wall_count, blue_count, green_count = self.count_image_color_pixels(img)\r\n        if yellow_count == 0 and red_count == 0 and black_count == 0 and white_count == 0 == 0 and blue_count == 0 and green_count == 0: return False\r\n        # print(f"yellow: {yellow_count}, red: {red_count}, white: {white_count}, black: {black_count}, blue: {blue_count}, green: {green_count}, wall: {wall_count}")\r\n        pixels = yellow_count + red_count + black_count + white_count + blue_count + green_count\r\n        color_pixels = sorted([yellow_count, red_count, black_count, white_count, blue_count, green_count], reverse = True)\r\n        wall_percentage = utils.get_percentage(pixels, wall_count)[1]\r\n        # print(f"wall percentage: {wall_percentage}")\r\n        if wall_percentage is None: return False\r\n        if wall_percentage > 80: return False\r\n        if color_pixels[0] < 500: return False\r\n\r\n        # NOTE (Martu): For no redetecting!\r\n        if white_count > 1 and black_count == 0: return False\r\n        if white_count >= 200 and black_count >= white_count * 0.4: return False\r\n        # if grey_count > 1: return False\r\n        # if white_count > 1 and black_count == 0: return False\r\n        # if white_count > 1 and (red_count != 0 or yellow_count != 0 or blue_count != 0 or green_count != 0): return False\r\n        if black_count > 1 and white_count == 0 and red_count == 0 and yellow_count == 0: return False # Si no hay blanco pero tampoco hay ni rojo ni amarillo (o sea, no es F/O)\r\n        if red_count > 1 and white_count == 0 and yellow_count == 0: return False # Si no hay blanco pero s\xc3\xad rojo, y no hay amarillo (o sea, no es O ni F)\r\n        if yellow_count > 1 and red_count == 0: return False # Si hay amarillo, pero no hay rojo, al no ser una O; no puede ser nada\r\n        if red_count > 1 and black_count > 1 and yellow_count == 0: return False # Si hay rojo pero no amarillo, o sea que es F y no O, no puede tener negro\r\n        if yellow_count > 1 and red_count > 1 and white_count > 1: return False # Si es O, no puede tener blanco\r\n        if black_count > 1 and white_count > 1 and (red_count > 1 or yellow_count > 1): return False # Si es P/C/S/H/U, no puede tener ni rojo ni amarillo\r\n        return True\r\n    \r\n    def is_zoomed_image_a_victim(self, img):\r\n        """Evaluates if the zoomed image is a victim or not."""\r\n        if img is None: return False\r\n        yellow_count, red_count, white_count, black_count, grey_count, wall_count, blue_count, green_count = self.count_image_color_pixels(img)\r\n        if yellow_count > 1 or red_count > 1 or blue_count > 1 or green_count > 1: return False\r\n        return True\r\n    \r\n    def contour_on_top_or_bottom_border(self, cnt):\r\n        """Checks if a contour is touching the top or bottom border."""\r\n        topmost = tuple(cnt[cnt[:,:,1].argmin()][0])\r\n        bottommost = tuple(cnt[cnt[:,:,1].argmax()][0])\r\n        if topmost[1] == 0 or topmost[1] == 39: return True\r\n        if bottommost[1] == 0 or bottommost[1] == 39: return True\r\n        return False\r\n    \r\n    def needs_contour_be_straightened(self, contour):\r\n        """Evaluates if the contour is deformed and needs to be straightened."""\r\n        if contour is None: return False\r\n        contour_area = cv2.contourArea(contour)\r\n        _, _, w, h = cv2.boundingRect(contour)\r\n        bounding_rect_area = w * h\r\n        if bounding_rect_area == 0: return False\r\n        area_ratio = contour_area / bounding_rect_area\r\n        print(f"Contour area: {contour_area}, Bounding rect area: {bounding_rect_area}, Area ratio: {area_ratio}")\r\n        if area_ratio < 0.9: # If the contour area is significantly smaller than the bounding rectangle area, it might be transformed\r\n            return True\r\n        return False\r\n    \r\n    def obtain_contours_centre(self, cnt):\r\n        """Returns the centre of a given contour."""\r\n        # print(f" Contour {cnt}")\r\n        if cnt is None or len(cnt) == 0: return None\r\n        contour_centre = cv2.minAreaRect(cnt)[0][0]\r\n        return contour_centre\r\n    \r\n    def get_contour_corners(self, contour):\r\n        """Obtains the four corners of a contour."""\r\n        if contour is None or len(contour) == 0: return None\r\n        pts = contour.reshape(-1, 2) # Reshape the contour to a 2D array of points\r\n\r\n        top_left_corner = pts[np.argmin(pts.sum(axis = 1))] # The top-left corner will have the smallest sum of x and y coordinates\r\n        top_right_corner = pts[np.argmin(np.diff(pts, axis = 1))] # The top-right corner will have the smallest difference between x and y coordinates\r\n        bottom_right_corner = pts[np.argmax(pts.sum(axis = 1))] # The bottom-right corner will have the largest sum of x and y coordinates\r\n        bottom_left_corner = pts[np.argmax(np.diff(pts, axis = 1))] # The bottom-left corner will have the largest difference between x and y coordinates\r\n        return top_left_corner, top_right_corner, bottom_right_corner, bottom_left_corner\r\n    \r\n    def is_analizable(self, contour, tol = 8):\r\n        """Compares the hieght and width of a contour to determine if it is analizable or not."""\r\n        _, _, w, h = cv2.boundingRect(contour)\r\n        # print(f"Contour width: {w}, height: {h}, difference: {abs(w - h)}")\r\n        if abs(w - h) > tol: return False\r\n        return True\r\n\r\n    def is_victim(self, img,  analyzing_after_placing = False):\r\n        """Evaluates if the image is an unseen sign or not."""\r\n        if img is None: return False\r\n        if img.size == 0: return False\r\n        contour, _ = self.clean_image_with_own_thresh(img,  analyzing_after_placing)\r\n        if contour is None: return False\r\n        yellow_count, red_count, white_count, black_count, grey_count, blue_count, green_count = self.count_color_pixels(img, contour)\r\n        if yellow_count > 1 or red_count > 1 or blue_count > 1 or green_count > 1: return False\r\n\r\n        # NOTE (Martu): For no obstacles detecting and/or redetecting!\r\n        if white_count == 0 or black_count == 0: return False\r\n\r\n        if len(contour) < 3: return False\r\n        contour_on_top_or_bottom_border = self.contour_on_top_or_bottom_border(contour)\r\n        if contour_on_top_or_bottom_border: \r\n            is_analizable = self.is_analizable(contour, tol = 8)\r\n            if not is_analizable: return False\r\n        contour_on_lateral_border = self.contour_on_lateral_border(contour)\r\n        if contour_on_lateral_border: \r\n            if not self.is_analizable(contour, tol = 8): return False\r\n        contour_area = cv2.contourArea(contour)\r\n        if contour_area < MIN_AREA: return False\r\n        is_analizable = self.is_analizable(contour, tol = 8)\r\n        if not is_analizable: return False\r\n        return True\r\n    \r\n    def is_cognitive(self, img,  analyzing_after_placing = False):\r\n        """Evaluates if the image is an unseen sign or not."""\r\n        if img is None: return False\r\n        if img.size == 0: return False\r\n        contour, _ = self.clean_cognitive_image_with_own_thresh(img,  analyzing_after_placing)\r\n        if contour is None: \r\n            return False\r\n        yellow_count, red_count, white_count, black_count, _, blue_count, green_count = self.count_color_pixels(img, contour)\r\n        # print(f"Yellow count: {yellow_count}, Red count: {red_count}, Black count: {black_count}, Blue count: {blue_count}, Green count: {green_count}")\r\n        if yellow_count == 0 and red_count == 0 and black_count == 0 and blue_count == 0 and green_count == 0: return False\r\n        # print(f"White count: {white_count}")\r\n        if white_count != 0: \r\n            # print(f"White pixels found in cognitive image, count: {white_count}")\r\n            return False\r\n        if len(contour) < 3: \r\n            return False\r\n        contour_on_top_or_bottom_border = self.contour_on_top_or_bottom_border(contour)\r\n        if contour_on_top_or_bottom_border: \r\n            is_analizable = self.is_analizable(contour, tol = 8)\r\n            if not is_analizable: \r\n                return False\r\n        contour_on_lateral_border = self.contour_on_lateral_border(contour)\r\n        if contour_on_lateral_border: \r\n            if not self.is_analizable(contour, tol = 8): \r\n                return False\r\n        contour_area = cv2.contourArea(contour)\r\n        if contour_area < MIN_COGNITIVE_AREA: \r\n            return False\r\n        is_analizable = self.is_analizable(contour, tol = 8)\r\n        if not is_analizable: \r\n            return False\r\n        # print(f"Cognitive contour area: {contour_area}") \r\n        return True\r\n    \r\n    def analyze_zoomed_image(self, img, last_position, last_direction):\r\n        """Zoomed images analysis logic."""\r\n        aux_img = img.copy()\r\n        if last_position.distance_to(self.last_token_position) < 0.015 and self.last_token_direction.dot(last_direction) > 0.9:\r\n            return None\r\n        if img is None or img.size == 0:\r\n            return None\r\n        yellow_count, red_count, white_count, black_count, grey_count, wall_count, blue_count, green_count = self.count_image_color_pixels(img)\r\n        if white_count != 0 and black_count != 0:\r\n            return \'S\'\r\n        else: return None\r\n    \r\n    def analyze_image(self, converted_img, last_position, last_direction):\r\n        """Image analysis logic, it returns a letter if the image is a sign, otherwise it returns None."""\r\n        if not self.debugging:\r\n            if last_position.distance_to(self.last_token_position) < 0.015 and self.last_token_direction.dot(last_direction) > 0.9:\r\n                return None\r\n        if converted_img is None or converted_img.size == 0:\r\n            return None\r\n        # self.debug_show(converted_img, "analyzing_img")\r\n        result = self.clean_image_with_own_thresh(converted_img)\r\n        contour, _ = result\r\n        if contour is not None:\r\n            yellow_count, red_count, white_count, black_count, grey_count, blue_count, green_count = self.count_color_pixels(converted_img, contour)\r\n            if yellow_count == 0 and red_count == 0 and black_count == 0 and white_count == 0 and grey_count == 0 and blue_count == 0 and green_count == 0: return None            \r\n            if self.is_victim(converted_img):\r\n                victim = self.return_victim_letter(converted_img, contour)\r\n                if victim is not None:\r\n                    self.last_token_position = last_position\r\n                    self.last_token_direction = last_direction\r\n                    return victim\r\n            elif self.is_cognitive(converted_img):\r\n                # hazard = self.return_hazard_letter(yellow_count, red_count, black_count, white_count)\r\n                cognitive = self.return_cognitive_letter(converted_img)\r\n                if cognitive is not None:\r\n                    self.last_token_position = last_position\r\n                    self.last_token_direction = last_direction\r\n                    return cognitive\r\n        else:\r\n            return \'Z\'\r\n\r\n# image = ImageProcessor()\r\n# # # # "C:\\Willow\\imgs\\ZoomedIn\\CD9449.png"\r\n# # # image_test\\other test\\A4 R3.png\r\n# img = cv2.imread("image_testing/obstacles/ci5318.png")\r\n# # # # "C:\\Willow\\image_test\\post_test4\\special front0766.png"\r\n# img = np.dstack((img, np.full([40,40], 255))).astype(np.uint8)\r\n\r\n# is_image_zoomed = image.is_image_zoomed_in(img)\r\n# print(f"Is image zoomed in: {is_image_zoomed}")\r\n\r\n# # is_cognitive = image.is_cognitive(img)\r\n# # print(f"Is cognitive: {is_cognitive}")\r\n\r\n# print(f"Letter: {image.analyze_image(img, Vector(0,0), Vector(1,0))}")\r\n\r\n# print(f"Is image: {image.is_image(img)}")\r\n# # grey = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)\r\n# # _, thresh = cv2.threshold(grey, 155, 255, cv2.THRESH_BINARY)\r\n# # image.debug_show(thresh, "img")\r\n# # # img_aux = img.copy()\r\n# # # img_aux = cv2.cvtColor(img_aux, cv2.COLOR_BGR2HSV)\r\n# # # image.debug_show(img_aux, "img_aux")\r\n# # # thresh = image.threshold_image(img)\r\n# # # image.debug_show(thresh, "thresh")\r\n# # # image.clean_image_with_own_thresh(img)\r\n# # # print(image.is_image(img))\r\n# # print(image.analyze_image(img, Vector(0,0), Vector(1,0)))\r\n# # # yellow_count, red_count, white_count, black_count, grey_count, wall_count = image.count_image_color_pixels(img)\r\n# # # print(f"white: {white_count}, black: {black_count}, wall: {wall_count}, red: {red_count}, yellow: {yellow_count}, grey: {grey_count}")\r\n# # # is_image_zoomed = image.is_image_zoomed_in(img)\r\n# # # print(f"Is image zoomed in: {is_image_zoomed}")\r\n# # # if is_image_zoomed:\r\n# # #     a = image.analyze_zoomed_image((img), Vector(0,0), Vector(1,0))\r\n# # #     print(f"Analyzed zoomed image: {a}")\r\n# # # contour_centre = image.get_contour_centre(img)\r\n# # # print(f"Contour centre: {contour_centre}")\r\n# # # print(image.analyze_zoomed_image(img, Vector(0,0), Vector(1,0)))\r\n# # # print(image.analyze_image(img, Vector(0,0), Vector(1,0)))\r\n# # # contour_centre = image.get_contour_centre(img)\r\n# # # print(f"Contour centre: {contour_centre}")\r\n# print("---------------------------------------------------------------------------------------------------")')
    __stickytape_write_module('lidar.py', b'import math\r\nfrom side import Side\r\nimport utils\r\n\r\nWALL_DIST = 0.0725\r\nALINEATION_DIST = 0.7\r\n\r\nclass LidarProcessor:\r\n    def is_wall_at_side(self, lidar_image, side):\r\n        dist = lidar_image[side.value]\r\n        # print(f"Distance at {side.name}: {dist}")\r\n        # utils.log_debug(f"Distance at {side.name}: {dist}")\r\n        return dist < WALL_DIST\r\n    \r\n    def is_aligned_to_wall(self, lidar_image, side, direction):\r\n        delta_ang = -math.pi*2/512\r\n        dist_a = lidar_image[side.value]\r\n        dist_b = lidar_image[side.value + 5]\r\n        if side == Side.LEFT:\r\n            direction = direction.rotated(math.pi/2)\r\n        elif side == Side.RIGHT:\r\n            direction = direction.rotated(-math.pi/2)\r\n        a = direction * dist_a\r\n        b = (direction * dist_b).rotated(delta_ang * 5)\r\n        c = (b - a).normalized()\r\n        # utils.log_debug(f"Robot\'s alineation to wall at {side.name}: {c.dot(direction)}, max: {ALINEATION_DIST}")\r\n        # print(f"Robot\'s alineation to wall at {side.name}: {c.dot(direction)}, max: {ALINEATION_DIST}")\r\n        # if c.dot(direction) < ALINEATION_DIST:\r\n        #     print(f"Robot is aligned to wall at {side.name}, alineation: {c.dot(direction)}, max: {ALINEATION_DIST}")\r\n        return c.dot(direction) < ALINEATION_DIST')
    __stickytape_write_module('comm.py', b'import struct\r\n\r\nclass MessageType:\r\n    GAME_INFO = \'G\'  # Game information\r\n    MAP = \'M\'  # Map information\r\n    EXIT = \'E\'  # Exit message\r\n    LOP = \'L\'  # LOP message\r\n    \r\n\r\nclass Comm:\r\n    def __init__(self, robot):\r\n        self.emitter = robot.emitter\r\n        self.receiver = robot.receiver\r\n        self.robot=robot\r\n\r\n    def send_token(self, pos_1, pos_2, letter):\r\n        """Sends a token message with the specified positions and letter."""\r\n        let = bytes(letter, \'utf-8\')  \r\n        message = struct.pack("i i c", pos_1, pos_2, let) \r\n        self.emitter.send(message)\r\n\r\n    def send_gamescore_and_time_remaining_request(self):\r\n        """Sends a request for game score and time remaining."""\r\n        message = struct.pack(\'c\', \'G\'.encode()) # message = \'G\' for game information\r\n        self.emitter.send(message) # send message     \r\n\r\n    def send_map(self, rep):\r\n        """Sends the map representation."""\r\n     ## Get shape\r\n        s = rep.shape\r\n        ## Get shape as bytes\r\n        s_bytes = struct.pack(\'2i\',*s)\r\n\r\n        ## Flattening the matrix and join with \',\'\r\n        flat_map = \',\'.join(rep.flatten())\r\n        ## Encode\r\n        sub_bytes = flat_map.encode(\'utf-8\')\r\n\r\n        ## Add togeather, shape + map\r\n        a_bytes = s_bytes + sub_bytes\r\n\r\n        ## Send map data\r\n        self.emitter.send(a_bytes)\r\n\r\n        #STEP3 Send map evaluate request\r\n        map_evaluate_request = struct.pack(\'c\', b\'M\')\r\n        self.emitter.send(map_evaluate_request)\r\n    \r\n    def send_exit(self):\r\n        """Sends an exit message to indicate the end of communication."""\r\n        ## Exit message\r\n        exit_mes = struct.pack(\'c\', b\'E\')\r\n        self.emitter.send(exit_mes)\r\n\r\n    def send_LOP(self): # Not used...\r\n        """Sends a LOP message."""\r\n        message = struct.pack(\'c\', \'L\'.encode())\r\n        self.emitter.send(message)\r\n\r\n    def get_messages(self):\r\n        """Retrieves messages from the receiver and processes them based on their type."""\r\n        messages = []\r\n        while self.receiver.getQueueLength() > 0:\r\n            message = self.receiver.getBytes()\r\n            # Check if the message is a game information message\r\n            if message[0] == ord(MessageType.GAME_INFO):\r\n                # Unpack the message\r\n                _, gs, tr, rtr, bat = struct.unpack(\'c f i i f\', message)\r\n                messages.append((MessageType.GAME_INFO, gs, tr, rtr, bat))\r\n            elif message[0] == ord(MessageType.LOP):\r\n                messages.append((MessageType.LOP))\r\n            self.receiver.nextPacket()\r\n            \r\n        return messages')
